// Canvas do radar acompanha dimensões CSS; só recalcula em mudança de layout.
function syncMinimapCanvasSize(){
  if(!minimap)return;
  const rect=minimap.getBoundingClientRect();
  const cssW=Math.max(1,Math.round(rect.width||minimap.clientWidth||minimap.width||220));
  const cssH=Math.max(1,Math.round(rect.height||minimap.clientHeight||minimap.height||220));
  const dpr=Math.min(window.devicePixelRatio||1, 1.5);
  const nextW=Math.max(1,Math.round(cssW*dpr));
  const nextH=Math.max(1,Math.round(cssH*dpr));
  if(minimap.width!==nextW) minimap.width=nextW;
  if(minimap.height!==nextH) minimap.height=nextH;
}
const $ = (s) => document.querySelector(s);

const QUALITY_STORAGE_KEY='stellar_quality_mode';
const DEVICE_CAPS=(()=>{
  const ua=String(navigator.userAgent||'');
  const coarse=matchMedia?.('(pointer: coarse)')?.matches||false;
  const mobile=/Android|iPhone|iPad|iPod|Mobile/i.test(ua)||coarse||innerWidth<=820;
  const memory=Number(navigator.deviceMemory)||0;
  const cores=Number(navigator.hardwareConcurrency)||0;
  const saveData=!!navigator.connection?.saveData;
  const reducedMotion=matchMedia?.('(prefers-reduced-motion: reduce)')?.matches||false;
  return {mobile,memory,cores,saveData,reducedMotion};
})();
function initialAutoQuality(){return initialAutoQualityForDevice(DEVICE_CAPS,innerWidth);}
