const PERF_MONITOR=createPerformanceMonitor();
const VISUAL_ISOLATION_V75=createVisualIsolationV75();
function syncVisualIsolationV75(){const state=VISUAL_ISOLATION_V75.snapshot(performance.now());document.body.dataset.visualTestV75=state.mode;const pill=document.getElementById('visualDiagFloatingV75');if(pill){pill.classList.toggle('hidden',!state.active);if(state.active)pill.textContent=state.pending?'V75: abra o mapa para iniciar':`V75 ${VISUAL_TEST_MODES_V75[state.mode]} • ${state.remainingSeconds??35}s • RESTAURAR`; } const status=document.getElementById('visualDiagStatusV75');if(status){const last=state.results.at(-1);status.textContent=state.reason+(last?` • último: ${last.label}, ${last.samples} quadros, ${Number.isFinite(last.fps)?last.fps.toFixed(1):'n/d'} FPS`:'');}}

const BROWSER_LATENCY_V72=createBrowserLatencyDiagnostics();
let perfHudVisible=false;
function perfHeapMb(){
  const bytes=Number(performance.memory?.usedJSHeapSize);
  return Number.isFinite(bytes)&&bytes>0?Math.round(bytes/1048576*10)/10:null;
}
function perfFormat(value,suffix=''){return Number.isFinite(value)?`${Math.round(value*10)/10}${suffix}`:'—';}
function updatePerfDiagnostics(){
  const stats=PERF_MONITOR.snapshot(),cache=ASSET_CACHE.stats(),heap=perfHeapMb();
  const gameStats=PERF_MONITOR.snapshot('game'),settingsStats=PERF_MONITOR.snapshot('settings');
  const active=stats.enabled;
  const value=(id,text)=>{const el=document.getElementById(id);if(el&&el.textContent!==text)el.textContent=text;};
  value('perfDiagHudFps',`FPS ${perfFormat(stats.fps)}`);
  value('perfDiagHudStutter',`P95 ${perfFormat(stats.frameP95Ms,' ms')} • engasgos ${stats.longFrames}`);
  document.getElementById('perfDiagOverlay')?.classList.toggle('hidden',!active||!perfHudVisible);
  // Fora de CONF, o relatório visível é só o contador; 17+ cards não precisam ser atualizados.
  if(!isSettingsOpenV2029())return;
  value('perfDiagFps',active?perfFormat(stats.fps):'—');
  value('perfDiagRafFps',active?perfFormat(stats.rafFps):'—');
  value('perfDiagRafP95',active?perfFormat(stats.rafP95Ms,' ms'):'—');
  value('perfDiagGateSkips',active?String(stats.rafSkipped)+' / '+String(stats.rafTotal):'—');
  value('perfDiagGameFps',active?perfFormat(gameStats.fps):'—');
  value('perfDiagSettingsFps',active?perfFormat(settingsStats.fps):'—');
  value('perfDiagGameSamples',active?String(gameStats.samples):'—');
  value('perfDiagSettingsSamples',active?String(settingsStats.samples):'—');
  value('perfDiagFrame',active?perfFormat(stats.frameP95Ms,' ms'):'—');
  value('perfDiagWork',active?perfFormat(stats.workP95Ms,' ms'):'—');
  value('perfDiagUpdate',active?perfFormat(stats.updateP95Ms,' ms'):'—');
  value('perfDiagDraw',active?perfFormat(stats.drawP95Ms,' ms'):'—');
  value('perfDiagWait',active?perfFormat(stats.waitP95Ms,' ms'):'—');
  value('perfDiagGameplay',active?perfFormat(stats.gameplayP95Ms,' ms'):'—');
  value('perfDiagServices',active?perfFormat(stats.servicesP95Ms,' ms'):'—');
  value('perfDiagHudCost',active?perfFormat(stats.hudP95Ms,' ms'):'—');
  value('perfDiagHudFull',active?perfFormat(stats.hudFullP95Ms,' ms'):'—');
  value('perfDiagHudCritical',active?perfFormat(stats.hudCriticalP95Ms,' ms'):'—');
  value('perfDiagHudAmmo',active?perfFormat(stats.hudAmmoP95Ms,' ms'):'—');
  value('perfDiagStutters',active?String(stats.longFrames):'—');
  value('perfDiagCache',active?`${cache.count} imagens • ${cache.failed} falha(s) • DPR ${DPR.toFixed(2)} • ${Math.round(canvas.width*canvas.height/1e6*10)/10} Mpix`:'—');
  value('perfDiagHeap',active?perfFormat(heap,' MB'):'—');
  const show=document.getElementById('perfDiagShowHud');
  if(show){show.checked=perfHudVisible&&active;show.disabled=!active;}
  const enabled=document.getElementById('perfDiagEnabled');if(enabled)enabled.checked=active;
  const copy=document.getElementById('perfDiagCopy');if(copy)copy.disabled=!active||stats.samples===0;
  const clear=document.getElementById('perfDiagReset');if(clear)clear.disabled=!active;
  const info=document.getElementById('perfDiagStatus');
  if(info&&!info.dataset.notification)info.textContent=!active?'Desligado. Nenhuma medição é coletada.':stats.samples<15?'Coletando amostras locais...':'Amostras locais: '+stats.samples+' (máximo de 240 quadros). FPS observado pode ser menor que o limite escolhido.';
}
function perfReport(){
  const main=formatPerformanceReport(PERF_MONITOR.snapshot(),{
    version:'47.7.37',quality:qualityBadgeLabel(),
    resolution:`${innerWidth}x${innerHeight} • Canvas ${canvas.width}x${canvas.height} • DPR ${DPR.toFixed(2)} • escala ${ADAPTIVE_CANVAS_V70.scale().toFixed(2)}`,heapMb:perfHeapMb(),cache:ASSET_CACHE.stats(),
    scenes:{game:PERF_MONITOR.snapshot('game'),settings:PERF_MONITOR.snapshot('settings')},
  });
  const v=VISUAL_PROFILE_V71.snapshot();
  const latency=BROWSER_LATENCY_V72.snapshot(),deferred=HUD_DEFERRED_V72.snapshot();
  const phases=RENDER_PHASES_V73.snapshot(),budget=HUD_BUDGET_V73.snapshot();
  const num=value=>Number.isFinite(value)?`${value.toFixed(1)} ms`:'não disponível';
  return main+`\nVISUAL V71 (último quadro) • base ${v.baseMs?.toFixed(1)||'—'}ms • portais ${v.portalMs?.toFixed(1)||'—'}ms • relés ${v.relayMs?.toFixed(1)||'—'}ms`
    +`\nV72 • tarefas longas ${latency.longTaskSupported?latency.longTaskCount:'API indisponível'} • P95 ${num(latency.longTaskP95Ms)} • máximo ${num(latency.longTaskMaxMs)}`
    +`\nV72 • atraso event-loop P95 ${num(latency.driftP95Ms)} • máximo ${num(latency.driftMaxMs)} (${latency.driftCount} amostras)`
    +`\nV72 • HUD completo fora do rAF: ${deferred.count} tarefas • última ${num(deferred.latestMs)} • máximo ${num(deferred.maximumMs)}`
    +`\nV73 • HUD periódico limitado: ${budget.accepted} ciclos, ${budget.skipped} adiados; intervalo ${budget.intervalMs} ms`
    +`\nV73 • render P95 fundo ${num(phases.backgroundP95Ms)} • estruturas ${num(phases.structuresP95Ms)} • entidades ${num(phases.actorsP95Ms)} • efeitos ${num(phases.effectsP95Ms)} • minimapa ${num(phases.minimapP95Ms)} (${phases.samples} quadros)`
    +'\nV73 • Compare em cena e orientação iguais à V72. Sem benchmark real, ganho de FPS não confirmado.'
    +`\nV76 • relés renderizados ${relayRenderDiagnosticV76().draws} • erros isolados ${relayRenderDiagnosticV76().failed} • último: ${relayRenderDiagnosticV76().lastError||'nenhum'}`
    +'\n'+VISUAL_ISOLATION_V75.report();
}
function togglePerfDiagnostics(active){
  PERF_MONITOR.setEnabled(active);if(active)BROWSER_LATENCY_V72.start();else BROWSER_LATENCY_V72.stop();if(!active){perfHudVisible=false;VISUAL_ISOLATION_V75.stop('Medições desativadas');syncVisualIsolationV75();}
  const info=document.getElementById('perfDiagStatus');if(info)delete info.dataset.notification;
  updatePerfDiagnostics();
}
const ASSET_CACHE=createAssetCache({
  createImage:()=>new Image(),
  now:()=>performance.now(),
  warn:(...message)=>console.warn(...message),
});
const requestAssetImage=ASSET_CACHE.requestAssetImage;
function trimAssetCache(){ASSET_CACHE.trimAssetCache(qualityProfile().assetCap||32);}
// V34.2.0: itens essenciais entram imediatamente; arte suplementar em pequenas
// fatias de tempo ocioso, sem forcar centenas de decodificacoes no boot.
const STAGED_PRELOADER_V342=createStagedAssetPreloader({
  request:requestAssetImage,
  schedule:callback=>{
    if(typeof requestIdleCallback==='function')requestIdleCallback(callback,{timeout:400});
    else setTimeout(callback,48);
  },
  batchSize:DEVICE_CAPS.mobile?2:4,
});
function preloadAssets(){
  requestAssetImage(GAME_ASSETS.loot?.cargo);
  requestAssetImage(GAME_ASSETS.bonus?.box);
  const paths=[...new Set(flattenAssetPaths(GAME_ASSETS))].filter(qualityShouldPreload);
  STAGED_PRELOADER_V342.enqueue(paths);
  setTimeout(trimAssetCache,1500);
}
function preloadActiveGameplayAssets(){
  if(!progress)return;
  // Nova area invalida pendencias de mundos anteriores; o cache de sprites ja
  // carregados permanece intacto para impedir flashes ao trocar de mapa.
  STAGED_PRELOADER_V342.clear();
  // Prioridade absoluta: mapa, sprite/sheet da nave, cargo e base visivel.
  for(const path of [currentMapBackground(),shipMapSheetAsset(progress.activeShipId),shipMapAsset(progress.activeShipId),
    GAME_ASSETS.loot?.cargo,GAME_ASSETS.bonus?.box,
    // V106: mapa astral desenhado em 2D; artes v38/gates permanecem no Materializador.
    ['x1','x8'].includes(progress.mapId)?(GAME_ASSETS.bases?.[currentTerritoryFaction()]||GAME_ASSETS.bases?.orbitalStation):null]){
    if(path)requestAssetImage(path);
  }
  const deferred=[
    ...Object.values(GAME_ASSETS.portals||{}),
    ...new Set((state.ores||[]).map(o=>o?.type).filter(Boolean).map(type=>GAME_ASSETS.resources?.[type])),
    shipCardAsset(progress.activeShipId),
    droneMapAsset(progress?.pet?.level>=10?'petElite':'pet'),
    droneMapSheetAsset(progress?.pet?.level>=10?'petElite':'pet'),
    droneCardAsset(progress?.pet?.level>=10?'petElite':'pet'),
  ];
  for(const d of progress.drones||[])deferred.push(droneMapAsset(d.type),droneMapSheetAsset(d.type),droneCardAsset(d.type));
  for(const e of state.enemies||[])if(e?.hp>0)deferred.push(npcMapSheetAsset(e.type),npcWorldSpriteAsset(e.type));
  for(const rp of onlineWorld?.players?.values?.()||[])deferred.push(shipMapSheetAsset(rp.shipId,rp.faction),shipMapAsset(rp.shipId,rp.faction));
  STAGED_PRELOADER_V342.enqueue(deferred);
  setTimeout(trimAssetCache,1200);
}
