const SAVE_KEY_PREFIX = 'stellarLegacyV5Save';
const SAFE_ZONE = { mapId: 'x1', x: 620, y: MAPS.x1.world.h / 2, radius: 520 };
const PORTAL_NEUTRAL_RADIUS = 240;

function basePointForFaction(factionId,mapId='x1'){
  const w=(MAPS[mapId]||MAPS.x1).world.w,h=(MAPS[mapId]||MAPS.x1).world.h;
  if(factionId==='mars') return {x:w-620,y:Math.round(h*.28)};
  if(factionId==='jupiter') return {x:w-620,y:Math.round(h*.72)};
  return {x:620,y:Math.round(h*.50)};
}
function currentBasePoint(){
  const owner=currentTerritoryFaction?.()||progress?.profile?.faction||'earth';
  return basePointForFaction(owner,progress?.mapId==='x8'?'x8':'x1');
}
let cloudDirty = false;
// V105: a resposta de um save antigo nunca pode limpar alterações feitas enquanto ele estava em voo.
let cloudSaveMutationV105=0;
let missionSavePendingV105=false;
// V109: equipamentos precisam de ACK do Supabase, sem afetar salvamentos economicos.
let equipmentSavePendingV109=false;
let equipmentSaveDesiredV109=null;
let equipmentSaveBaselineV109=null;
let equipmentSaveTimerV109=null;
let equipmentSaveWarningAtV109=0;
// V106.2: intencao explicita de equipamento persiste entre fechar/reabrir APK.
// Um save local mais recente (por combate) NAO e intencao de retirar itens.
function equipmentIntentKeyV1062(){return `stellar_hangar_write_intent_v1062_${getUser()?.id||'none'}`;}
function readEquipmentIntentV1062(){try{return JSON.parse(localStorage.getItem(equipmentIntentKeyV1062())||'null');}catch{return null;}}
function persistEquipmentIntentV1062(){
  try{if(progress&&equipmentSaveBaselineV109)localStorage.setItem(equipmentIntentKeyV1062(),JSON.stringify({
    owner:getUser()?.id,baseline:equipmentLayoutSignatureV1062(equipmentSaveBaselineV109),
    desired:equipmentLayoutSignatureV1062(progress),createdAt:Date.now()
  }));}catch(e){console.warn('[hangar-v1062] journal',e);}
}
function clearEquipmentIntentV1062(){try{localStorage.removeItem(equipmentIntentKeyV1062());}catch{}}

let saveIntegrityBlockedV106=false; // Conflito de equipamento ainda nao resolvido: proibe compra/venda.
// V106.1: a preferencia de disparo fica pendente ate ACK do Supabase.
// Nunca transporta quantidade de municao ou saldos do cliente para a reconciliacao.
const AMMO_SELECTION_V1061=createAmmoSelectionTrackerV1061({
  laserIds:Object.keys(LASER_AMMO),rocketIds:Object.keys(ROCKETS)
});
let ammoSelectionSaveTimerV1061=null;
let ammoSelectionOwnerV1061=null;
function scheduleAmmoSelectionSaveV1061(delay=180){
  if(!authenticated||!progress||offlineFarmWorldLockedV84()||!AMMO_SELECTION_V1061.pending)return;
  if(ammoSelectionSaveTimerV1061!==null)clearTimeout(ammoSelectionSaveTimerV1061);
  ammoSelectionSaveTimerV1061=setTimeout(()=>{
    ammoSelectionSaveTimerV1061=null;
    if(authenticated&&!offlineFarmWorldLockedV84())void flushCloudSave(true);
  },delay);
}
function changeAmmoSelectionV1061(kind,id){
  if(!authenticated||!progress||offlineFarmWorldLockedV84())return false;
  const key=kind==='laser'?'selectedLaserAmmo':kind==='rocket'?'selectedRocket':null;
  if(!key||!AMMO_SELECTION_V1061.accepts(key,id))return false;
  if(progress[key]===id)return true;
  progress[key]=id;
  AMMO_SELECTION_V1061.mark(key,id);
  saveGame();refreshAmmoCounters(true);
  setSync('MUNICAO PENDENTE','busy');
  scheduleAmmoSelectionSaveV1061();
  return true;
}

function rememberEquipmentChangeV109(){
  if(!authenticated||!progress||offlineFarmWorldLockedV84())return;
  equipmentSavePendingV109=true;equipmentSaveWarningAtV109=0;
  equipmentSaveDesiredV109=structuredClone(progress);
  persistEquipmentIntentV1062();
  setSync('HANGAR PENDENTE','busy');
  scheduleEquipmentSaveV109(180);
}
function scheduleEquipmentSaveV109(delay=250){
  if(!equipmentSavePendingV109||!authenticated||offlineFarmWorldLockedV84())return;
  if(equipmentSaveTimerV109!==null)clearTimeout(equipmentSaveTimerV109);
  equipmentSaveTimerV109=setTimeout(()=>{
    equipmentSaveTimerV109=null;
    if(!cloudBusy){void flushCloudSave(true);}
    // Quando houver save concorrente, o finally do flush em andamento reenfileira.
  },delay);
}
function equipmentSavedV109(snapshot){
  if(!equipmentSavePendingV109)return;
  if(equipmentFingerprintV109(snapshot)!==equipmentFingerprintV109(equipmentSaveDesiredV109))return;
  equipmentSavePendingV109=false;equipmentSaveDesiredV109=null;equipmentSaveWarningAtV109=0;
  clearEquipmentIntentV1062();
  saveIntegrityBlockedV106=false;
  if(equipmentSaveTimerV109!==null){clearTimeout(equipmentSaveTimerV109);equipmentSaveTimerV109=null;}
  setSync('HANGAR SALVO','ok');
  showToast('Hangar confirmado no Supabase ✓','system');
}
function equipmentRecoveryWarningV109(){
  saveIntegrityBlockedV106=true;
  const now=Date.now();
  setSync('HANGAR NAO SALVO','err');
  if(now-equipmentSaveWarningAtV109>20000){
    equipmentSaveWarningAtV109=now;
    showToast('Montagem nao confirmada: verifique o hangar antes de sair do APK.','system');
  }
}

const MISSION_REWARD_ACK_V108=createMissionRewardAckV108();
let missionRewardOwnerV108=null;
function announceCommittedMissionRewardsV108(savedMissions){
  for(const draft of MISSION_REWARD_ACK_V108.acknowledge(savedMissions)){
    telemetryEconomy('mission',{cr:draft.bonus.credits,stl:draft.bonus.uridium,xp:draft.bonus.xp});
    telemetryCounter('missions_completed',1);
    showMissionCompleteAnimation(draft.mission,draft.bonus);
    showToast(`Recompensa confirmada • ${draft.mission.title}${draft.surprise?.label?` • ${draft.surprise.label}`:''}`,'mission');
  }
}
let missionSaveTimerV105=null;
function queueMissionSaveV105(){
  if(!authenticated||!progress||offlineFarmWorldLockedV84())return;
  missionSavePendingV105=true;
  if(missionSaveTimerV105!==null)clearTimeout(missionSaveTimerV105);
  missionSaveTimerV105=setTimeout(()=>{
    missionSaveTimerV105=null;
    if(!cloudBusy&&cloudDirty)void flushCloudSave(false);
  },350);
}

let cloudBusy = false;
let authenticated = false;
// Login bootstrap must never expose a half-initialized world (HP 1/1, empty NPC map, etc.).
const gameBootstrapRuntime={loading:false,ready:false,generation:0,lastError:null};
function bootstrapDelay(ms){return new Promise(resolve=>setTimeout(resolve,ms));}


// ===================== V15.1 SHARED UNIVERSE • REALTIME COMBAT PRESENCE =====================
const sharedUniverseRuntime={ready:false,status:'offline',latency:0,event:null,globalEvent:null,warfront:null,roomKey:null,lastPlayerSyncAt:0,lastCombatSignature:'',lastPlayerSentX:null,lastPlayerSentY:null,lastPlayerSentAngle:null,lastPlayerSentHp:null,lastPlayerSentShield:null,pendingOres:new Set(),lastSnapshotToastAt:0,mapError:null,sectorFallback:null,sectorReadPending:false,sectorReadAt:0,sectorReadError:null,sectorReadGeneration:0};
const SHARED_SYNC_COMBAT_MS=100;
const SHARED_SYNC_MOVE_MS=100; // V34.6.3: cruise multiplayer, ~10 Hz por piloto.
const SHARED_SYNC_IDLE_MS=3000; // Somente heartbeat leve em repouso; combate permanece em 100ms.
function sharedUniverseMap(){return !!authenticated&&!!progress&&!isGalaxyGateMap();}
function sharedUniverseOnline(){return sharedUniverseMap()&&sharedUniverseRuntime.ready&&sharedUniverse.isOnline();}
function updateSharedUniverseChip(){
  if(!ui.worldSyncLabel)return;
  const view=universeConnectionStatusV1066({status:sharedUniverseRuntime.status,mapId:progress?.mapId,latency:sharedUniverseRuntime.latency,reason:sharedUniverseRuntime.mapError});
  ui.worldSyncLabel.textContent=view.label;
  ui.worldSyncLabel.title=view.title;
  ui.worldSyncLabel.setAttribute('aria-label',view.title);
  const st=sharedUniverseRuntime.status;
  ui.worldSyncLabel.className=`sync-chip world-chip ${st==='online'?'ok':st==='reconnecting'||st==='connecting'?'busy':st==='offline'?'':'err'}`.trim();
}
function sharedWorldEvent(){return sharedUniverseRuntime.event||null;}
function visibleSharedWorldEvent(){
  const local=sharedWorldEvent();if(local)return local;
  const global=sharedUniverseRuntime.globalEvent;
  if(!global||!Number.isFinite(Number(global.end))||Date.now()>=Number(global.end))return null;
  // Eventos exclusivos de outra região são informativos. Não criam NPCs nem progresso local.
  return {...global,informationalOnly:true};
}
const READ_ONLY_SECTOR_LAYOUT={b41:[['A','ALPHA',.26,.32],['B','BETA',.54,.52],['C','GAMMA',.79,.67]],b42:[['A','ALPHA',.23,.68],['B','BETA',.52,.38],['C','GAMMA',.78,.65]],b43:[['A','ALPHA',.22,.34],['B','BETA',.52,.66],['C','GAMMA',.80,.38]]};
function sectorControlState(){
  if(!state.currentMap?.battle)return null;
  if(sharedUniverseRuntime.ready&&sharedUniverseRuntime.warfront?.mapId===progress?.mapId)return sharedUniverseRuntime.warfront;
  return sharedUniverseRuntime.sectorFallback?.mapId===progress?.mapId?sharedUniverseRuntime.sectorFallback:null;
}
function normalizeReadOnlySectorOwnership(mapId,rows,map){
  if(!READ_ONLY_SECTOR_LAYOUT[mapId]||!Array.isArray(rows)||rows.length!==3)return null;
  const byId=new Map(rows.map(row=>[String(row.node_id||''),row]));
  const scores={earth:0,mars:0,jupiter:0};
  const w=Number(map?.world?.w)||6000,h=Number(map?.world?.h)||4500;
  const nodes=READ_ONLY_SECTOR_LAYOUT[mapId].map(([id,label,nx,ny])=>{
    const row=byId.get(id);if(!row)return null;
    const owner=['earth','mars','jupiter'].includes(row.owner)?row.owner:null;
    if(owner)scores[owner]++;
    return {id,label,x:Math.round(w*nx),y:Math.round(h*ny),radius:360,owner,challenger:null,progress:0,contested:false,nearby:{earth:0,mars:0,jupiter:0},capturedAt:Date.parse(row.captured_at||'')||0};
  });
  if(nodes.some(x=>!x))return null;
  return {mapId,nodes,scores,dominantFaction:null,readOnly:true};
}
async function refreshSectorReadOnly(force=false){
  const mapId=String(progress?.mapId||'');if(!authenticated||!READ_ONLY_SECTOR_LAYOUT[mapId])return;
  if(sharedUniverseRuntime.ready&&!force)return;
  if(sharedUniverseRuntime.sectorReadPending)return;
  if(!force&&Date.now()-sharedUniverseRuntime.sectorReadAt<12000)return;
  const generation=sharedUniverseRuntime.sectorReadGeneration;
  sharedUniverseRuntime.sectorReadPending=true;sharedUniverseRuntime.sectorReadAt=Date.now();
  try{
    const data=await loadSectorOwnershipOnline(mapId);
    if(generation!==sharedUniverseRuntime.sectorReadGeneration||String(progress?.mapId)!==mapId)return;
    const snapshot=normalizeReadOnlySectorOwnership(mapId,data?.nodes,state.currentMap);
    if(!snapshot)throw new Error('Dados de domínio incompletos.');
    sharedUniverseRuntime.sectorFallback=snapshot;sharedUniverseRuntime.sectorReadError=null;
    updateWarfrontBadge();
    if(ui.warfrontModal&&!ui.warfrontModal.classList.contains('hidden'))renderWarfront();
  }catch(err){
    if(generation===sharedUniverseRuntime.sectorReadGeneration){sharedUniverseRuntime.sectorReadError=String(err?.message||'Sem conexão com o banco').slice(0,140);if(ui.warfrontModal&&!ui.warfrontModal.classList.contains('hidden'))renderWarfront();}
  }finally{sharedUniverseRuntime.sectorReadPending=false;}
}

function sectorFactionColor(id){return FACTIONS[id]?.color||'#b7c8d4';}
function sectorFactionLabel(id){return FACTIONS[id]?.short||'NEUTRO';}
function sectorControlScore(id){return Math.max(0,Number(sectorControlState()?.scores?.[id])||0);}
function sectorControlNearbyTotal(node){return Object.values(node?.nearby||{}).reduce((s,n)=>s+Math.max(0,Number(n)||0),0);}
// V34.6: PvP relays are server-owned structures; no client may declare ownership or damage.
const relayAttackRuntime={nodeId:null,waitingNodeId:null,interval:null,lastShotSec:0};
const relayWorkshopRuntime={state:null,loading:false,lastAt:0,active:null,mapId:null,errors:0};
const relayHangarRuntime={mapId:null,nodeId:null,selectedSlot:1,busy:false};
const relayMissionBusy=new Set();
function relayCurrentBonus(){
 const st=relayWorkshopRuntime.state;if(!st?.enabled||!progress)return null;
 const clanId=st.clan?.id,mod=st.installedModules||[];
 const local=st.nodes?.filter(n=>n.map_id===progress.mapId&&n.owner_clan_id===clanId&&clanId)||[];
 const options=[];
 for(const m of mod){if(m.category!=='bonus'||!(m.level>=1&&m.level<=3))continue;
   if(!local.some(n=>n.map_id===m.map_id&&n.node_id===m.node_id))continue;
   const val=({damage:[3,4,5],shield:[5,7,9],hp:[5,7,9],speed:[2,3,4],xp:[5,7,10],resources:[3,4,5]})[m.attribute]?.[m.level-1];
   if(val)options.push({attribute:m.attribute,level:m.level,value:val});
 }
 if(st.global?.active)options.push(st.global.active);
 options.sort((a,b)=>b.level-a.level||b.value-a.value||String(a.attribute).localeCompare(String(b.attribute)));
 return options[0]||null;
}
function relayGlobalBonusPct(attr){const b=relayWorkshopRuntime.active;return b?.attribute===attr?Math.max(0,Number(b.value)||0):0;}
async function refreshRelayWorkshop(force=false){
 if(!authenticated||!progress)return;
 // Never discard a forced refresh after an equip/craft. Wait for a concurrent read,
 // then fetch again so the freshly committed module appears immediately.
 if(relayWorkshopRuntime.loading){
   if(force&&relayWorkshopRuntime.inflight){await relayWorkshopRuntime.inflight.catch(()=>{});return refreshRelayWorkshop(true);}
   return;
 }
 if(!force&&Date.now()-relayWorkshopRuntime.lastAt<45000)return;
 relayWorkshopRuntime.loading=true;
 const dominionVisible=!!ui.warfrontModal&&!ui.warfrontModal.classList.contains('hidden');
 const domRequest=dominionVisible?loadDominionStateOnline():Promise.resolve(relayWorkshopRuntime.state?.dominion||{ok:false,error:'Abra a Frente de Guerra para consultar o Domínio Galáctico.'});
 const frontierRequest=dominionVisible?loadFrontierStateOnline():Promise.resolve(relayWorkshopRuntime.state?.frontier||{ok:false,error:'Abra a Frente de Guerra para consultar expedições.'});
 const request=Promise.allSettled([loadRelayDominationOnline(),domRequest,frontierRequest]);relayWorkshopRuntime.inflight=request;
 try{const settled=await request,primary=settled[0],secondary=settled[1];
   if(primary.status!=='fulfilled')throw primary.reason;
   const data=primary.value,previous=JSON.stringify(relayWorkshopRuntime.active);
   data.dominion=secondary.status==='fulfilled'?secondary.value:{ok:false,error:'SQL V36 ou rede indisponível; sistemas anteriores continuam ativos.'};
   data.frontier=settled[2]?.status==='fulfilled'?settled[2].value:{ok:false,error:'SQL V37 ou rede indisponível; sistemas anteriores continuam ativos.'};
   relayWorkshopRuntime.state=data;relayWorkshopRuntime.lastAt=Date.now();relayWorkshopRuntime.errors=0;relayWorkshopRuntime.active=relayCurrentBonus();
   if(previous!==JSON.stringify(relayWorkshopRuntime.active))computeStats(true);
 }catch(err){relayWorkshopRuntime.errors++;if(relayWorkshopRuntime.errors===1)console.warn('[relay-state]',String(err?.message||err));}
 finally{relayWorkshopRuntime.loading=false;relayWorkshopRuntime.inflight=null;if(ui.warfrontModal&&!ui.warfrontModal.classList.contains('hidden'))renderWarfront();renderRelayHangar();}
}
function relayCombatPanelHtml(sc){
 return `<div class="relay-combat-v346"><div class="section-kicker">RELAY DOMINATION • CONQUISTA 24H</div><div class="relay-combat-grid-v346">${(sc.nodes||[]).map(n=>{
 const sh=Math.max(0,Number(n.shield)||0),hp=Math.max(0,Number(n.hp)||0),maxSh=Math.max(1,Number(n.maxShield)||240000),maxHp=Math.max(1,Number(n.maxHp)||360000),prot=Date.now()<Number(n.protectedUntil||0);
 return `<article class="relay-combat-card-v346"><div><b>${escHtml(n.label||n.id)} • ${escHtml(n.id)}</b><small>${n.ownerClanId?'CLÃ DOMINANTE':'FACÇÃO / NEUTRO'} • ${escHtml(sectorFactionLabel(n.owner))}</small></div><small>ESCUDO ${fmt(sh)} / ${fmt(maxSh)}</small><div class="relay-meter-v346 shield"><i style="width:${Math.round(sh/maxSh*100)}%"></i></div><small>HP ${fmt(hp)} / ${fmt(maxHp)}</small><div class="relay-meter-v346 hull"><i style="width:${Math.round(hp/maxHp*100)}%"></i></div><small>${prot?'PROTEÇÃO TEMPORÁRIA':hp<=0?'NÚCLEO VULNERÁVEL • ENTRE NA ZONA':'DESTRUA O RELÉ PARA CONQUISTAR'}</small><small class="relay-map-hint">Toque no relé diretamente no mapa para mirar e atacar.</small></article>`;}).join('')}</div></div>`;
}
function stopRelayAttack(){if(relayAttackRuntime.interval)clearInterval(relayAttackRuntime.interval);relayAttackRuntime.interval=null;relayAttackRuntime.nodeId=null;relayAttackRuntime.waitingNodeId=null;}
function selectRelayWorld(node){
 if(!node?.relayMode||!sharedUniverseOnline())return false;
 if(relayWorkshopRuntime.state?.clan?.id&&node.ownerClanId===relayWorkshopRuntime.state.clan.id){openRelayHangar(progress.mapId,node.id);return true;}
 if(node.ownerClanId&&!relayWorkshopRuntime.state?.clan?.id){refreshRelayWorkshop(true).then(()=>{if(node.ownerClanId===relayWorkshopRuntime.state?.clan?.id)openRelayHangar(progress.mapId,node.id);}).catch(()=>{});showToast('Conferindo posse do relé...');return true;}
 state.target=null;player.laserFiring=false;updateTargetLockHud();state.pointerNavActive=false;
 // Click twice to cancel. One click selects and follows the target as NPCs do.
 if(relayAttackRuntime.nodeId===node.id||relayAttackRuntime.waitingNodeId===node.id){stopRelayAttack();showToast('Ataque ao relé interrompido.');return true;}
 stopRelayAttack();
 if(Number(node.hp)<=0){showToast('Núcleo vulnerável: aproxime-se para conquistar.');player.tx=node.x;player.ty=node.y;return true;}
 if(Date.now()<Number(node.protectedUntil||0)){showToast('Relé sob proteção temporária.');return true;}
 const dist=Math.hypot(player.x-node.x,player.y-node.y);
 if(dist>1120){
   relayAttackRuntime.waitingNodeId=node.id;
   const distance=Math.max(1,dist),stopAt=850;
   player.tx=node.x+(player.x-node.x)*stopAt/distance;
   player.ty=node.y+(player.y-node.y)*stopAt/distance;
   showToast('RELÉ '+node.id+' selecionado • aproximando para atacar');
 }else{toggleRelayAttack(node.id);}
 return true;
}
function updateRelayTargetApproach(){
 const id=relayAttackRuntime.waitingNodeId;if(!id)return;
 const node=sectorControlState()?.nodes?.find(n=>n.id===id);
 if(!node||!node.relayMode||!sharedUniverseOnline()||!state.currentMap?.battle||Number(node.hp)<=0||Date.now()<Number(node.protectedUntil||0)){stopRelayAttack();return;}
 if(Math.hypot(player.x-node.x,player.y-node.y)<=1090){relayAttackRuntime.waitingNodeId=null;toggleRelayAttack(id);}
}

function fireRelayLaserPulse(nodeId){
 if(!progress||!sharedUniverseOnline()||!authenticated)return false;
 const ids=equippedLaserIds();
 if(ids.length<1){showToast('Equipe lasers no hangar da nave para atacar relés.');stopRelayAttack();return false;}
 let ammo=currentLaserAmmo(),stock=ammoQty(ammo.id);
 if(stock<=0){ammo=recoverActiveLaser(ammo.id,true);if(!ammo){showToast('Sem munição laser para atacar o relé.');stopRelayAttack();return false;}stock=ammoQty(ammo.id);}
 const count=laserAmmoShotBudgetV1064(ids.length,stock).spent;
 if(count<=0)return false;
 if(!sharedUniverse.attackRelay(nodeId))return false;
 // Disparar no relé consome munição como o ataque PvE. O servidor calcula dano pelo save.
 progress.ammo[ammo.id]=Math.max(0,stock-count);
 battlePassEvent('ammoUse',count);refreshAmmoCounters();saveGame();playSfx('laser');
 relayAttackRuntime.lastShotSec=nowSec();
 return true;
}
function toggleRelayAttack(nodeId){
 if(relayAttackRuntime.nodeId===nodeId){stopRelayAttack();renderWarfront();return;}
 if(!sharedUniverseOnline()||!state.currentMap?.battle){showToast('Entre online em um mapa PvP para atacar o relé.');return;}
 const n=sectorControlState()?.nodes?.find(x=>x.id===nodeId);
 if(!n||Math.hypot(player.x-n.x,player.y-n.y)>1200){showToast('Aproxime-se a até 1.200 unidades do relé.');return;}
 stopRelayAttack();relayAttackRuntime.nodeId=nodeId;fireRelayLaserPulse(nodeId);
 relayAttackRuntime.interval=setInterval(()=>{
   const current=sectorControlState()?.nodes?.find(x=>x.id===nodeId);
   if(!authenticated||!sharedUniverseOnline()||!current?.relayMode||Number(current.hp)<=0||Date.now()<Number(current.protectedUntil||0)||Math.hypot(player.x-current.x,player.y-current.y)>1200){stopRelayAttack();return;}
   fireRelayLaserPulse(nodeId);
 },700);renderWarfront();
}
