function sectorControlNodeHtml(node){const owner=node?.owner||null,challenger=node?.challenger||null,ownerLabel=owner?sectorFactionLabel(owner):'NEUTRO',ownerColor=owner?sectorFactionColor(owner):'#8aa0ad',challengeLabel=node?.captureError?'ERRO DE GRAVAÇÃO':node?.persisting?'CONFIRMANDO...':node?.contested?'CONTESTADO':challenger?'CAPTURANDO':'ESTÁVEL',challengeColor=node?.contested?'#ffffff':challenger?sectorFactionColor(challenger):ownerColor,progress=Math.max(0,Math.min(100,Number(node?.progress)||0)),near=sectorControlNearbyTotal(node);return `<article class="sector-node-card${node?.contested?' contested':''}" style="--sector-owner:${ownerColor};--sector-challenge:${challengeColor}"><div class="sector-node-symbol">${escHtml(node?.id||'?')}</div><div class="sector-node-main"><div><b>${escHtml(node?.label||'PONTO')}</b><small>${escHtml(ownerLabel)} • ${near} PILOTO(S) NA ZONA</small></div><strong>${escHtml(challengeLabel)}</strong></div><div class="sector-node-track"><i style="width:${progress}%"></i></div><div class="sector-node-foot"><span>${node?.captureError?escHtml(node.captureError.message||'Falha ao salvar no banco'):node?.persisting?'AGUARDANDO CONFIRMAÇÃO NO BANCO':challenger?`${escHtml(sectorFactionLabel(challenger))} • ${Math.round(progress)}%`:owner?'SETOR CONTROLADO':'AGUARDANDO CAPTURA'}</span>${state.currentMap?.battle?`<button class="ghost-btn" data-warfront-nav="${escHtml(node?.id||'')}">IR</button>`:''}</div></article>`;}
function sectorControlPanelHtml(){const sc=sectorControlState();if(!state.currentMap?.battle)return `<section class="warfront-panel sector-control-panel"><div class="section-kicker">CONTROLE DE SETOR</div><div class="sector-control-empty"><b>ENTRE EM 4-1 / 4-2 / 4-3</b><span>Os pontos de controle são sincronizados pelo Shared Universe quando você entra em um Battle Map.</span></div></section>`;if(!sc)return `<section class="warfront-panel sector-control-panel"><div class="section-kicker">CONTROLE DE SETOR</div><div class="sector-control-empty"><b>${sharedUniverseRuntime.mapError?'SALA PvP INDISPONÍVEL':'SINCRONIZANDO SETOR...'}</b><span>${escHtml(sharedUniverseRuntime.mapError||sharedUniverseRuntime.sectorReadError||'Aguardando o estado tático do servidor.')}</span><button class="ghost-btn" data-warfront-reconnect>TENTAR NOVAMENTE</button></div></section>`;const scores=sc.scores||{},dominant=sc.dominantFaction||null;return `<section class="warfront-panel sector-control-panel"><div class="sector-control-head"><div><div class="section-kicker">CONTROLE DE SETOR • ${escHtml(displayMapLabel(progress.mapId))}</div><h3>${dominant?`${escHtml(sectorFactionLabel(dominant))} EM VANTAGEM`:'SETOR DISPUTADO'}</h3><small>${sc.readOnly?'VISUALIZAÇÃO DO BANCO • Conexão PvP indisponível. A captura e os eventos aguardam a sala online.':'Destrua os escudos e o núcleo do relé no mapa e aproxime-se para conquistar. Mais aliados aceleram a ocupação.'}</small></div><div class="sector-scoreboard">${['earth','mars','jupiter'].map(id=>`<div style="--faction:${sectorFactionColor(id)}"><span>${escHtml(sectorFactionLabel(id))}</span><b>${fmt(scores[id]||0)}/3</b></div>`).join('')}</div></div><div class="sector-node-grid">${(sc.nodes||[]).map(sectorControlNodeHtml).join('')}</div><div class="warfront-rule-banner">${sc.readOnly?`<b>CONTROLE OFFLINE:</b> ${escHtml(sharedUniverseRuntime.mapError||'Aguardando o servidor PvP.')} <button class="ghost-btn" data-warfront-reconnect>RECONECTAR</button>`:'<b>DOMÍNIO PERSISTENTE:</b> ataque o relé no mapa para derrubar as defesas e conquistar para seu clã. A facção também é registrada.'}</div>${sc.relayMode?relayCombatPanelHtml(sc):''}</section>`;}

const warbotBeamsV477=[];
function handleWarbotMessageV477(msg){
  if(msg.type==='warbot_clear'){
    const ids=new Set(msg.ids||[]);state.enemies=state.enemies.filter(e=>!ids.has(e.id));
    if(state.target&&ids.has(state.target.id)){state.target=null;player.laserFiring=false;}
    return true;
  }
  if(msg.type==='warbot_state'){
    const ids=new Set((msg.bots||[]).map(e=>String(e.id||'')));
    state.enemies=state.enemies.filter(e=>!e.warBot||ids.has(String(e.id)));
    for(const raw of msg.bots||[]){
      if(!String(raw.id||'').startsWith('warbot_'))continue;
      const prev=findSharedNpc(raw.id);
      if(prev)applySharedNpcPatch(raw);
      else state.enemies.push(normalizeSharedNpc(raw));
    }
    if(state.target?.warBot&&!ids.has(String(state.target.id))){state.target=null;player.laserFiring=false;}
    return true;
  }
  if(msg.type==='warbot_damage_result'){
    const e=findSharedNpc(msg.entityId);if(e&&msg.actual>0){
      e.hp=Number(msg.hp??e.hp);e.shield=Number(msg.shield??e.shield);
      spawnCombatText(e.x,e.y-e.size,'BOT -'+fmt(msg.actual),'#ffd89b',{kind:'damage'});
      spawnImpactFx(e.x,e.y,'#ffb675',26,'impact');
    }
    // Warbot damage never completes passes, missions, quests, economy or PVP kill stats.
    return true;
  }
  if(msg.type==='warbot_spar_hit'){
    if(progress&&state.currentMap?.battle)spawnCombatText(player.x,player.y-45,'TREINO -'+fmt(Number(msg.estimatedDamage)||0),'#ebc868',{kind:'incoming'});
    return true;
  }
  if(msg.type==='warbot_fire'){
    if(!state.currentMap?.battle)return true;
    const a=msg.from||{},b=msg.to||{};
    if(Number.isFinite(Number(a.x))&&Number.isFinite(Number(a.y))&&Number.isFinite(Number(b.x))&&Number.isFinite(Number(b.y))){
      // Avoid allocating beams or unlocking audio for battles that cannot appear on-screen.
      // The draw loop already applies this same world-visibility check.
      if(!onScreenWorld(Number(a.x),Number(a.y),160)&&!onScreenWorld(Number(b.x),Number(b.y),160))return true;
      warbotBeamsV477.push({a:{x:Number(a.x),y:Number(a.y)},b:{x:Number(b.x),y:Number(b.y)},color:String(msg.color||'#77cfff'),created:nowSec()});
      if(warbotBeamsV477.length>12)warbotBeamsV477.shift();
      playSfx('petLaser');
    }
    return true;
  }
  return false;
}
function drawWarbotBeamsV477(){
  const now=nowSec(),quality=resolvedQualityMode();
  for(let i=warbotBeamsV477.length-1;i>=0;i--){
    const f=warbotBeamsV477[i];
    if(now-f.created>.22){warbotBeamsV477.splice(i,1);continue;}
    if(!onScreenWorld(f.a.x,f.a.y,160)&&!onScreenWorld(f.b.x,f.b.y,160))continue;
    drawWarbotBeamV477(ctx,{...f,a:screenPos(f.a.x,f.a.y),b:screenPos(f.b.x,f.b.y)},now,quality);
  }
}
function normalizeSharedNpc(raw){
  const base=NPC_TYPES[raw.type]||{},x=Number(raw.x)||0,y=Number(raw.y)||0;return {...raw,x,y,tx:x,ty:y,netX:x,netY:y,netAt:Date.now(),vx:0,vy:0,visualAngle:Number(raw.angle)||0,sharedWorld:true,name:raw.name||base.name||raw.type,color:raw.color||base.color||'#ff755d',size:Number(raw.size||base.size||18),resources:{...(raw.resources||base.resources||{})},lastShot:0,lastAttackPlayerAt:0,jammedUntil:Number(raw.jammedUntil)||0,bossAttackScale:Number(raw.bossAttackScale)||1};
}
function joinSharedUniverse(){
  if(offlineFarmWorldLockedV84()||!sharedUniverseMap())return;const sameSector=sharedUniverseRuntime.sectorFallback?.mapId===progress?.mapId;sharedUniverseRuntime.ready=false;sharedUniverseRuntime.mapError=null;sharedUniverseRuntime.warfront=null;sharedUniverseRuntime.sectorReadGeneration++;if(!sameSector)sharedUniverseRuntime.sectorFallback=null;sharedUniverseRuntime.sectorReadError=null;sharedUniverseRuntime.pendingOres.clear();sharedUniverseRuntime.lastPlayerSyncAt=0;sharedUniverseRuntime.lastCombatSignature='';sharedUniverseRuntime.lastPlayerSentX=null;sharedUniverseRuntime.lastPlayerSentY=null;sharedUniverseRuntime.lastPlayerSentAngle=null;sharedUniverseRuntime.lastPlayerSentHp=null;sharedUniverseRuntime.lastPlayerSentShield=null;state.enemyRespawns=[];state.oreRespawns=[];
  if(state.currentMap?.battle)refreshSectorReadOnly(true).catch(()=>{});
  sharedUniverse.join({mapId:progress.mapId,territoryFaction:currentTerritoryFaction()||'battle',faction:progress.profile.faction,callsign:progress.profile.callsign||getUser()?.callsign||'Pilot',pilotTitle:activePilotTitle().label,shipId:progress.activeShipId,shipDesignId:currentShipDesign()?.design_id||null,level:progress.profile.level||1,x:player.x,y:player.y,angle:player.angle||0,hp:player.hp,maxHp:player.maxHp,shield:player.shield,maxShield:player.maxShield});
}
function syncSharedUniversePlayer(force=false){
  if(offlineFarmWorldLockedV84()||!sharedUniverseMap()||!sharedUniverse.isOnline())return;
  const now=Date.now(),ammo=currentLaserAmmo(),target=state.target&&state.target.hp>0?state.target:null,petOwned=!!progress.pet?.owned,petLaserActive=petOwned&&!!petRuntime.laserTargetId&&nowSec()<petRuntime.laserUntil;
  const combatSignature=[player.laserFiring?1:0,ammo?.id||'',target?.id||'',target?.isPlayer?1:0,petOwned?1:0,petRuntime.laserTargetId||'',petLaserActive?1:0,progress.pet?.activeGear||'off',currentShipDesignId()||'',currentPetDesignId()||''].join('|');
  const hasLast=Number.isFinite(sharedUniverseRuntime.lastPlayerSentX)&&Number.isFinite(sharedUniverseRuntime.lastPlayerSentY);
  const moved=!hasLast||Math.hypot(player.x-sharedUniverseRuntime.lastPlayerSentX,player.y-sharedUniverseRuntime.lastPlayerSentY)>=3;
  const angle=Number(player.angle)||0,lastAngle=Number(sharedUniverseRuntime.lastPlayerSentAngle);
  const angleMoved=!Number.isFinite(lastAngle)||Math.abs(angleDelta(lastAngle,angle))>=0.035;
  const hp=Math.max(0,Math.round(Number(player.hp)||0)),shield=Math.max(0,Math.round(Number(player.shield)||0));
  const vitalsChanged=hp!==sharedUniverseRuntime.lastPlayerSentHp||shield!==sharedUniverseRuntime.lastPlayerSentShield;
  const combatChanged=combatSignature!==sharedUniverseRuntime.lastCombatSignature;
  const inCombat=!!player.laserFiring||petLaserActive||!!target?.isPlayer;
  const minInterval=inCombat||combatChanged?SHARED_SYNC_COMBAT_MS:(moved||angleMoved||vitalsChanged?SHARED_SYNC_MOVE_MS:SHARED_SYNC_IDLE_MS);
  if(!force&&!combatChanged&&now-sharedUniverseRuntime.lastPlayerSyncAt<minInterval)return;

  const x=Math.round(Number(player.x)||0),y=Math.round(Number(player.y)||0),sentAngle=Math.round(angle*1000)/1000;
  const sent=sharedUniverse.updatePlayer({
    x,y,angle:sentAngle,hp,maxHp:Math.max(1,Math.round(Number(player.maxHp)||1)),shield,maxShield:Math.max(0,Math.round(Number(player.maxShield)||0)),
    faction:progress.profile.faction,shipId:progress.activeShipId,level:progress.profile.level||1,pilotTitle:activePilotTitle().label,shipDesignId:currentShipDesign()?.design_id||null,
    laserFiring:!!player.laserFiring&&!!target,laserColor:ammo?.color||'#76d9ff',laserAmmoId:ammo?.id||'lcb10',laserAmmoName:ammo?.name||'PLS-1',targetId:target?.id||null,targetIsPlayer:!!target?.isPlayer,
    pet:petOwned?{owned:true,level:progress.pet.level||1,x:Math.round(Number(petRuntime.x)||0),y:Math.round(Number(petRuntime.y)||0),angle:Math.round((Number(petRuntime.angle)||0)*1000)/1000,activeGear:progress.pet.activeGear||'off',laserTargetId:petRuntime.laserTargetId||null,laserActive:petLaserActive,laserColor:ammo?.color||'#76d9ff',designId:currentPetDesign()?.design_id||null}:{owned:false}
  });
  if(sent){
    sharedUniverseRuntime.lastPlayerSyncAt=now;
    sharedUniverseRuntime.lastCombatSignature=combatSignature;
    sharedUniverseRuntime.lastPlayerSentX=x;
    sharedUniverseRuntime.lastPlayerSentY=y;
    sharedUniverseRuntime.lastPlayerSentAngle=sentAngle;
    sharedUniverseRuntime.lastPlayerSentHp=hp;
    sharedUniverseRuntime.lastPlayerSentShield=shield;
  }
}
function findSharedNpc(id){return state.enemies.find(e=>e.id===id&&e.sharedWorld)||null;}
function purgeSharedEventEntities(activeEventId=null){
  const targetWasEvent=!!state.target?.eventNpc;
  state.enemies=state.enemies.filter(e=>!e.eventNpc||(activeEventId&&e.eventId===activeEventId));
  state.ores=state.ores.filter(o=>!o.eventOre||(activeEventId&&o.eventId===activeEventId));
  state.enemyRespawns=state.enemyRespawns.filter(r=>!r.eventId);
  state.oreRespawns=state.oreRespawns.filter(r=>!r.eventId&&!r.eventOre);
  if(targetWasEvent&&!state.enemies.some(e=>e.id===state.target?.id)){state.target=null;player.laserFiring=false;}
  galaxyEventRuntime.convoy=null;
}
function applySharedNpcPatch(raw){const e=findSharedNpc(raw.id);if(!e)return;mergeNpcMotionPatch(e,raw,Date.now());const rest={...raw};delete rest.x;delete rest.y;Object.assign(e,rest);}
function sharedKillReward(entity,factor=1,opts={}){
  if(!progress)return;
  const share=Math.max(0,Math.min(1,Number(factor)||0));
  const clone=normalizeSharedNpc({...entity,
    credits:Math.max(0,Math.round((entity.credits||0)*share)),
    uridium:Math.max(0,Math.round((entity.uridium||0)*share)),
    xp:Math.max(0,Math.round((entity.xp||0)*share)),
    resources:{...(entity.resources||{})},sharedReward:true,sharedRewardShare:share,
    sharedFinalBlow:false,sharedDropBox:!!opts.dropBox,sharedGroupReward:!!opts.groupShared,sharedOwner:!!opts.owner
  });

  // V18.0.0: membros elegíveis recebem somente a parcela econômica do NPC.
  // Kill/missão/conquista/passe/clã pertencem ao primeiro atacante, evitando farm passivo de objetivos.
  const xpMult=1+pilotSkillValue('tactics')/100;
  const reward=opts.serverReward;
  const approved=reward&&typeof reward==='object'&&Number.isSafeInteger(Number(reward.revision))&&Number(reward.revision)>0;
  if(!approved){showToast('Abate sem confirmação de créditos do servidor.','system');return;}
  const creditedRevision=Math.max(0,Number(progress.serverNpcRewardRevision)||0);
  if(Number(reward.revision)<=creditedRevision)return; // pacote duplicado, jamais soma duas vezes
  const earnedCredits=reward.granted===true?Math.max(0,Math.round(Number(reward.credits)||0)):0,
        earnedUri=reward.granted===true?Math.max(0,Math.round(Number(reward.stl)||0)):0,
        earnedXp=Math.round((Number(clone.xp)||clone.credits/10+clone.uridium*12)*xpMult*designerXpMultiplier());
  // CR/STL chegam do Supabase; XP e os objetivos legados continuam na progressão local.
  progress.serverNpcRewardRevision=Number(reward.revision);
  progress.profile.credits+=earnedCredits;
  progress.profile.uridium+=earnedUri;
  progress.profile.xp+=earnedXp;
  telemetryEconomy('npc',{cr:earnedCredits,stl:earnedUri,xp:earnedXp});

  if(opts.owner){
    progress.profile.aliensKilled=(progress.profile.aliensKilled||0)+1;
    telemetryCounter('kills',1);journeyEvent('kill',1);syncAchievements(true);
    if(authenticated){
      const boss=/^boss/i.test(String(clone.type||'')),clanType=String(clone.type||'').replace(/^boss/i,'').toLowerCase();
      recordClanAlienKillOnline({npcType:clanType,isBoss:boss}).then(r=>{if(r?.status?.leveled_up){showToast(`CLÃ SUBIU PARA O LV ${r.status.new_level}!`,'reward');refreshClanState(true);}}).catch(()=>{});
    }
    if(String(clone.type||'').startsWith('boss')){
      rollRareBossLoot(clone);
      scoreClanWar(Math.max(1,Math.round(10*share)),'boss_kill');
    }
    addPetXp(petXpForNpc(clone));
    missionEvent('kill',{enemy:clone,mapId:progress.mapId});
    battlePassEvent('kill',1);
  }
  processPlayerLevelUps();
  if(opts.dropBox)spawnNpcLootBox(clone);
  saveGame();

  const suffix=opts.groupShared?`GRUPO ${Math.max(1,Number(opts.eligibleCount)||1)} PILOTO(S)`:(opts.owner?'MARCAÇÃO EXCLUSIVA':'ABATE');
  pushActivity(`${suffix} • ${clone.name} • +${fmt(earnedCredits)} CR • +${fmt(earnedUri)} STL • +${fmt(earnedXp)} XP`,'combat');
}
function sharedNpcClaimState(e){
  const owner=String(e?.ownerUserId||''),me=String(getUser()?.id||'');if(!owner)return {claimed:false,friendly:false,owner:false};
  const myGroup=String(battleGroupState()?.group?.id||''),ownerGroup=String(e?.ownerGroupId||'');
  return {claimed:true,owner:owner===me,friendly:owner===me||!!(myGroup&&ownerGroup&&myGroup===ownerGroup)};
}
const warfrontAnnouncementQueue=[];
let warfrontAnnouncementRunning=false;
function warfrontAnnouncementElement(){
  let el=document.getElementById('warfrontGlobalAnnouncement');
  if(el)return el;
  el=document.createElement('div');el.id='warfrontGlobalAnnouncement';el.className='warfront-global-announcement';
  el.innerHTML='<div class="warfront-global-kicker">TRANSMISSÃO GLOBAL</div><strong></strong><span></span>';
  document.body.appendChild(el);return el;
}
function playNextWarfrontAnnouncement(){
  if(warfrontAnnouncementRunning||!warfrontAnnouncementQueue.length)return;
  warfrontAnnouncementRunning=true;
  const msg=warfrontAnnouncementQueue.shift(),el=warfrontAnnouncementElement();
  el.className=`warfront-global-announcement ${escHtml(msg.kind||'warfront_point')}`;
  el.querySelector('strong').textContent=String(msg.title||'WARFRONT');
  el.querySelector('span').textContent=String(msg.subtitle||'');
  requestAnimationFrame(()=>el.classList.add('show'));
  try{playSfx(msg.kind==='warfront_domination'?'reward':'warning');}catch{}
  pushActivity(`${msg.title||'WARFRONT'}${msg.subtitle?` • ${msg.subtitle}`:''}`,'combat');
  setTimeout(()=>{el.classList.remove('show');setTimeout(()=>{warfrontAnnouncementRunning=false;playNextWarfrontAnnouncement();},320);},4200);
}
function queueWarfrontGlobalAnnouncement(msg){
  if(!msg)return;
  warfrontAnnouncementQueue.push(msg);
  if(warfrontAnnouncementQueue.length>6)warfrontAnnouncementQueue.splice(0,warfrontAnnouncementQueue.length-6);
  playNextWarfrontAnnouncement();
}

function handleSharedUniverseMessage(msg){
  if(handleWarbotMessageV477(msg))return;
  if(!msg||!progress)return;
  if(msg.type==='join_error'){
    sharedUniverseRuntime.ready=false;
    sharedUniverseRuntime.mapError=String(msg.reason||'Falha ao entrar na sala PvP.').slice(0,190);
    refreshSectorReadOnly(true).catch(()=>{});
    if(ui.warfrontModal&&!ui.warfrontModal.classList.contains('hidden'))renderWarfront();
    const deniedFrontier=/^u[1-3]$/.test(progress.mapId)&&(/MAP_JOIN_DENIED|nível mínimo|Requer nível|Setor indisponível/i.test(String(msg.reason||'')));
    if(deniedFrontier){
      // Do not display a fake empty U-X room after a failed authoritative join.
      sharedUniverseRuntime.ready=false;
      // Display the actual server-side rejection; level 30 alone cannot fix a bad room partition.
      showToast('U-X • '+sharedUniverseRuntime.mapError,'system');
    }else showToast('MAPA • '+sharedUniverseRuntime.mapError,'system');
    return;
  }
  if(msg.type==='world_snapshot'){
    sharedUniverseRuntime.mapError=null;
    const targetId=state.target&&!state.target.isPlayer?state.target.id:null;state.enemies=(msg.npcs||[]).map(normalizeSharedNpc);state.ores=(msg.ores||[]).map(o=>({...o,sharedWorld:true}));state.enemyRespawns=[];state.oreRespawns=[];for(const rp of msg.players||[])upsertRealtimePlayer(rp,true);sharedUniverseRuntime.event=msg.event||null;sharedUniverseRuntime.globalEvent=msg.globalEvent||null;sharedUniverseRuntime.warfront=msg.warfront||null;sharedUniverseRuntime.mapError=null;sharedUniverseRuntime.roomKey=msg.roomKey||null;sharedUniverseRuntime.ready=true;galaxyEventRuntime.convoy=msg.event?.convoy?{...msg.event.convoy}:null;if(targetId){const e=findSharedNpc(targetId);state.target=e||null;if(!e)player.laserFiring=false;}const now=Date.now();if(now-sharedUniverseRuntime.lastSnapshotToastAt>3000){sharedUniverseRuntime.lastSnapshotToastAt=now;showToast(`UNIVERSO SINCRONIZADO • ${state.enemies.length} NPCs • ${state.ores.length} recursos`,'system');}updateSharedUniverseChip();return;
  }
  if(msg.type==='world_player_spawn'||msg.type==='world_player_patch'){upsertRealtimePlayer(msg.entity||{},msg.type==='world_player_spawn');return;}
  if(msg.type==='world_player_leave'){const id=String(msg.userId||'');if(state.target?.isPlayer&&state.target.id===id){state.target=null;player.laserFiring=false;}onlineWorld.players.delete(id);return;}
  if(msg.type==='warfront_capture_result'){
    if(msg.ok){showToast(`PONTO ${String(msg.nodeId||'?')} CONQUISTADO • CONFIRMADO NO SERVIDOR`,'reward');refreshSectorReadOnly(true).catch(()=>{});}
    else{showToast(`PONTO ${String(msg.nodeId||'?')} • ${String(msg.message||'Não foi possível confirmar a captura.').slice(0,150)}`,'system');}
    if(ui.warfrontModal&&!ui.warfrontModal.classList.contains('hidden'))renderWarfront();
    return;
  }
  if(msg.type==='relay_turret_attack'){const amount=Math.min(20000,Math.max(0,Number(msg.damage)||0));if(amount>0){takePlayerDamage(amount,{forceNpcRetaliation:true});queueRelayTurretBolt(msg);spawnParticle(player.x,player.y-36,(msg.weapon==='missile'?'MÍSSIL RELÉ':'LASER RELÉ')+' -'+fmt(amount),msg.weapon==='missile'?'#ffb36b':'#7ee9ff');}return;}
  if(msg.type==='relay_turret_fx'){if(state.currentMap?.battle&&Math.hypot(player.x-Number(msg.x||0),player.y-Number(msg.y||0))<1700){spawnParticle(Number(msg.x||0),Number(msg.y||0)-46,msg.weapon==='missile'?'LANÇAMENTO DE MÍSSIL':'LASER DEFENSIVO',msg.weapon==='missile'?'#ffad59':'#55dfff');}return;}
  if(msg.type==='relay_hit_result'){if(msg.ok===false&&msg.reason)showToast(String(msg.reason).slice(0,100));return;}
  if(msg.type==='relay_hit_fx'){if(!state.currentMap?.battle)return;const n=sectorControlState()?.nodes?.find(x=>x.id===msg.nodeId);if(n){n.shield=Number(msg.shield)||0;n.hp=Number(msg.hp)||0;spawnParticle(n.x,n.y-45,`-${fmt(msg.actual||0)}`,n.shield>0?'#5dcfff':'#ff7d66');spawnRelayVisualImpact(n);}return;}
  if(msg.type==='warfront_control'){sharedUniverseRuntime.warfront=msg.warfront||null;updateWarfrontBadge();if(ui.warfrontModal&&!ui.warfrontModal.classList.contains('hidden'))renderWarfront();return;}
  if(msg.type==='global_announcement'){queueWarfrontGlobalAnnouncement(msg);return;}
  if(msg.type==='npc_batch'){for(const e of msg.entities||[])applySharedNpcPatch(e);return;}
  if(msg.type==='npc_patch'){applySharedNpcPatch(msg.entity||{});return;}
  if(msg.type==='npc_claim'){const e=findSharedNpc(msg.entityId);if(e){e.ownerUserId=msg.ownerUserId||null;e.ownerGroupId=msg.ownerGroupId||null;e.claimedAt=Number(msg.claimedAt)||Date.now();}return;}
  if(msg.type==='npc_spawn'){const e=normalizeSharedNpc(msg.entity||{});if(e.id&&!findSharedNpc(e.id))state.enemies.push(e);return;}
  if(msg.type==='npc_remove'){const id=String(msg.entityId||'');state.enemies=state.enemies.filter(e=>String(e.id)!==id);if(state.target&&!state.target.isPlayer&&String(state.target.id)===id){state.target=null;player.laserFiring=false;}return;}
  if(msg.type==='npc_death'){
    const e=findSharedNpc(msg.entity?.id)||normalizeSharedNpc(msg.entity||{});if(e?.id){playSfx('explosion');spawnExplosionFx(e.x,e.y,e.color,String(e.type||'').startsWith('boss'));triggerCombatFlash(String(e.type||'').startsWith('boss')?'red':'cyan');state.enemies=state.enemies.filter(x=>x.id!==e.id);if(state.target?.id===e.id){state.target=null;player.laserFiring=false;autoAcquireNextTarget(e.id);}}return;
  }
  if(msg.type==='kill_credit'){const me=String(getUser()?.id||'');sharedKillReward(msg.entity||{},msg.factor,{serverReward:msg.serverReward,groupShared:!!msg.groupShared,eligibleCount:msg.eligibleCount,dropBox:!!msg.dropBox,owner:String(msg.ownerUserId||'')===me});return;}
  if(msg.type==='npc_reward_error'){showToast('NPC • '+String(msg.message||'Falha no pagamento do abate').slice(0,140),'system');return;}
  if(msg.type==='npc_loot_credit'){const e=normalizeSharedNpc(msg.entity||{});spawnNpcLootBox(e);pushActivity(`BOX EXCLUSIVA • ${e.name} • primeira marcação`,'reward');return;}
  if(msg.type==='damage_result'){
    const e=findSharedNpc(msg.entityId);if(e){e.hp=Number(msg.hp??e.hp);e.shield=Number(msg.shield??e.shield);if(msg.ownerUserId!==undefined)e.ownerUserId=msg.ownerUserId||null;if(msg.ownerGroupId!==undefined)e.ownerGroupId=msg.ownerGroupId||null;if(msg.actual>0){const shieldHit=Number(msg.beforeShield||0)>Number(msg.shield||0);spawnCombatText(e.x,e.y-e.size,msg.critical?`CRÍTICO ${fmt(msg.actual)}`:`-${fmt(msg.actual)}`,msg.critical?'#ffe96f':(shieldHit?'#62dcff':'#ff8b8b'),{critical:!!msg.critical,kind:shieldHit?'shield':'damage'});spawnImpactFx(e.x,e.y,shieldHit?'#55d8ff':'#ff6b77',shieldHit?30:22,shieldHit?'shield':'impact');battlePassEvent('damage',msg.actual);battlePassEvent('attack',1);}if(msg.mode==='shield_drain'&&msg.actual>0){const before=player.shield;player.shield=Math.min(player.maxShield,player.shield+Number(msg.actual||0));const gain=Math.max(0,Math.round(player.shield-before));if(gain)spawnParticle(player.x,player.y-34,`ESCUDO +${fmt(gain)}`,'#79f1ff');}}return;
  }
  if(msg.type==='ore_remove'){sharedUniverseRuntime.pendingOres.delete(msg.entityId);state.ores=state.ores.filter(o=>o.id!==msg.entityId);return;}
  if(msg.type==='ore_spawn'){const o={...(msg.ore||{}),sharedWorld:true};if(o.id&&!state.ores.some(x=>x.id===o.id))state.ores.push(o);return;}
  if(msg.type==='ore_collect_result'){sharedUniverseRuntime.pendingOres.delete(msg.entityId);if(msg.ok===false&&msg.reason==='persistence_error')showToast('MINÉRIO • sem confirmação do servidor. Tente novamente.','system');return;}
  if(msg.type==='ore_collected'){
    const o=msg.ore;if(!o)return;
    const receipt=msg.reward;
    if(!receipt||!Number.isSafeInteger(Number(receipt.revision))||Number(receipt.revision)<1){showToast('Coleta aguardando confirmação do servidor.','system');return;}
    sharedUniverseRuntime.pendingOres.delete(o.id);state.ores=state.ores.filter(x=>x.id!==o.id);
    const localOreRevision=Math.max(0,Number(progress.serverOreRevision)||0);
    if(Number(receipt.revision)<=localOreRevision)return;
    // Recibos podem chegar fora de ordem no multiplayer; um salto ou um replay
    // jamais autoriza sobrescrever o porão completo com apenas o último minério.
    if(Number(receipt.revision)!==localOreRevision+1||receipt.granted!==true){
      loadCloudSave().then(remote=>{if(remote?.state&&authenticated)installEconomyState(remote.state);})
        .catch(err=>console.warn('[ore-reconcile]',String(err?.message||err).slice(0,150)));
      return;
    }
    const got=receipt.granted===true?Math.max(0,Math.trunc(Number(receipt.amount)||0)):0;
    progress.serverOreRevision=Number(receipt.revision);
    if(got>0){progress.cargo[o.type]=(Number(progress.cargo[o.type])||0)+got;
    playSfx('pickup');spawnParticle(o.x,o.y,`${msg.collector==='pet'?'AUX-9 ':''}+${fmt(got)} ${stellarOreName(o.type)}`,o.color);pushActivity(`${msg.collector==='pet'?'AUX-9 MINERAÇÃO':'RECURSO ONLINE'} • +${fmt(got)} ${stellarOreName(o.type)}`,'ore');telemetryCounter('ore_nodes',1);telemetryCounter('ore_units',got);titleStatAdd('oreUnits',got);journeyEvent('ore',got);missionEvent('collectOre',{amount:got,type:o.type,mapId:progress.mapId});if(msg.collector==='pet')addPetXp(3);saveGame();}return;
  }
  if(msg.type==='npc_aggro'){const e=findSharedNpc(msg.entityId);if(e)e.aggroUserId=msg.userId||null;if(String(msg.userId||'')===String(getUser()?.id||'')){state.portalCombatUntil=Math.max(state.portalCombatUntil,nowSec()+6);setCombatAlert('NPC FIXOU ALVO EM VOCÊ','combat',1.4);}return;}
  if(msg.type==='npc_attack'){const e=findSharedNpc(msg.entityId);const retaliation=!!msg.retaliation;if(retaliation&&isPortalNeutralZone())state.portalCombatUntil=Math.max(state.portalCombatUntil,nowSec()+6);const hit=takePlayerDamage(Math.max(0,Number(msg.damage)||0),{forceNpcRetaliation:retaliation});if(e&&hit>0)e.lastAttackPlayerAt=nowSec();return;}
  if(msg.type==='event_cleanup'){
    const npcIds=new Set(msg.npcIds||[]),oreIds=new Set(msg.oreIds||[]);
    if(npcIds.size)state.enemies=state.enemies.filter(e=>!npcIds.has(e.id));else purgeSharedEventEntities(null);
    if(oreIds.size)state.ores=state.ores.filter(o=>!oreIds.has(o.id));
    if(state.target?.eventNpc&&(!state.enemies.some(e=>e.id===state.target.id))){state.target=null;player.laserFiring=false;}
    galaxyEventRuntime.convoy=null;return;
  }
  if(msg.type==='event_update'){
    const previousEventId=sharedUniverseRuntime.event?.eventId||null,nextEventId=msg.event?.eventId||null;
    sharedUniverseRuntime.event=msg.event||null;sharedUniverseRuntime.globalEvent=msg.globalEvent||null;
    if(previousEventId!==nextEventId||!nextEventId||msg.event?.complete)purgeSharedEventEntities(nextEventId&&!msg.event?.complete?nextEventId:null);
    galaxyEventRuntime.convoy=msg.event?.convoy?{...msg.event.convoy}:null;
    // Atualizar o HUD já ao receber o evento. Não esperar o próximo portal/mapa.
    if(progress){const active=currentGalaxyEvent();if(active.id==='none')ui.galaxyEventHud?.classList.add('hidden');else renderGalaxyEventHud(active,galaxyEventRecord(active));}
    // O progresso global da SALA nunca substitui a missão individual persistida no Supabase.
    return;
  }
  if(msg.type==='event_personal_update'){
    if(!sharedWorldEvent())return; // Evento apenas informativo não recebe progresso nem prêmio.
    const ev=currentGalaxyEvent(),data=msg.personal||{};
    if(!ev?.eventId||String(msg.eventId)!==String(ev.eventId)||String(data.eventId)!==String(ev.eventId))return;
    const rec=galaxyEventRecord(ev);
    rec.value=Math.max(Number(rec.value)||0,Math.max(0,Math.min(ev.target,Number(data.progress)||0)));
    // Não remover nunca um estado de recompensa já entregue no save.
    rec.rewarded=!!rec.rewarded||!!data.rewarded;
    rec.complete=!!rec.rewarded||!!data.complete;
    if(data.rewardedNow&&data.state){
      // O servidor já aplicou créditos/STL/XP e registrou a recompensa UMA vez.
      installEconomyState(data.state);
      const fresh=galaxyEventRecord(ev);fresh.value=ev.target;fresh.complete=true;fresh.rewarded=true;
      playSfx('event');triggerCombatFlash('gold');
      const r=data.reward||{};
      queueCelebration('mission',ev.name,`+${fmt(r.credits||0)} CR • +${fmt(r.uridium||0)} STL • +${fmt(r.xp||0)} XP`);
      pushActivity(`EVENTO • ${ev.name} concluído e registrado no servidor`,'reward');
      claimEventDesignerDrop(ev).catch(()=>{});
    }
    saveGame();renderGalaxyEvent();renderGalaxyEventHud(ev,galaxyEventRecord(ev));return;
  }
  if(msg.type==='event_personal_error'){
    showToast(msg.message||'Falha ao sincronizar evento.','system');return;
  }
  if(msg.type==='event_credit')return; // Evento legado: premiação agora exclusivamente via RPC.
}
const OFFLINE_FARM_V484=createOfflineFarmV484({
  credentials:()=>getSessionCredentials(),
  saveBeforeStart:async()=>{
    if(!authenticated||!progress||gameBootstrapRuntime.loading)throw Error('Aguarde o salvamento do personagem.');
    // V91: flushCloudSave previously returned immediately when another save was pending.
    await waitCloudIdle(12000);
    if(cloudBusy)throw Error('Um save ainda está em andamento. Tente iniciar o farm novamente.');
    await flushCloudSave(true);
    await waitCloudIdle(12000);
    if(cloudBusy||cloudDirty||AMMO_SELECTION_V1061.pending||equipmentSavePendingV109)throw Error('O save não foi confirmado pelo servidor. Farm não iniciado.');
  },
  onPauseWorld:async()=>{player.laserFiring=false;state.target=null;state.pointerNavActive=false;state.pointerNavId=null;player.tx=player.x;player.ty=player.y;ui.mapModal?.classList.add('hidden');sharedUniverse.close();},
  onResumeWorld:async()=>{if(authenticated&&progress&&!offlineFarmWorldLockedV84()){joinSharedUniverse();void syncOnlineWorld();}},
  onFinish:async()=>{
    /* STELLAR_FARM_RECOVER_SESSION_V495 - nunca sair da conta por resgatar/cancelar. */
    try{
      const currentAccount=String(getUser()?.id||'');
      if(!authenticated||!currentAccount)throw Error('Sessão do piloto ausente');
      // Um PUT de antes do resgate jamais pode terminar depois e regravar o farm.
      await waitCloudIdle(12000);
      if(cloudBusy)throw Error('Farm resgatado, mas existe save em voo: reconecte com seguranca.');
      const serverSave=await loadCloudSave();
      if(!serverSave?.state)throw Error('Save no servidor ainda indisponível');
      /* O snapshot antigo do PWA não pode sobrescrever o resgate SQL. */
      cloudDirty=false;
      try{localStorage.setItem(saveKey(),JSON.stringify({...serverSave.state,clientSavedAt:0}));}catch{}
      await afterAuth();
      if(!authenticated||String(getUser()?.id||'')!==currentAccount)throw Error('Falha ao retomar sessão');
      showToast('🌙 Farm finalizado • recompensas sincronizadas, piloto conectado','system');
    }catch(err){
      console.warn('[farm-v495] sincronização pós-farm',err);
      showToast('Farm finalizado. Sincronização pendente: tente ATUALIZAR no menu.','system');
    }
  }
});
