const MOBILE_COMBAT_LAYOUT_KEY='stellar_mobile_combat_compact_v3210';
function setMobileCombatCompact(enabled,persist=true){
  document.body.classList.toggle('mobile-combat-pro',!!enabled);
  const button=document.getElementById('mobileCombatModeBtn');
  if(button){button.setAttribute('aria-pressed',String(!!enabled));button.textContent=enabled?'EXPANDIR':'COMPACTO';}
  if(persist)try{localStorage.setItem(MOBILE_COMBAT_LAYOUT_KEY,enabled?'1':'0');}catch{}
  requestHudLayoutV2024();
}
function setupMobileCombatCompact(){
  const button=document.getElementById('mobileCombatModeBtn');
  if(!button)return;
  let enabled=DEVICE_CAPS.mobile;
  try{const saved=localStorage.getItem(MOBILE_COMBAT_LAYOUT_KEY);if(saved!==null)enabled=saved==='1';}catch{}
  setMobileCombatCompact(enabled,false);
  button.addEventListener('click',()=>setMobileCombatCompact(!document.body.classList.contains('mobile-combat-pro')));
}
