function galaxyEventProfile(ev=currentGalaxyEvent()){return eventControlProfile(GALAXY_EVENT_VARIANTS[String(ev?.id||'')]||GALAXY_EVENT_VARIANTS.invasion,ev?.rules?.event_control,true);}
function normalizeGalaxyEvents(){if(!progress)return;progress.galaxyEvents ||= {records:{},lastSeenEvent:null};progress.galaxyEvents.records ||= {};}
function currentGalaxyEvent(){
  const shared=sharedUniverseMap()?visibleSharedWorldEvent():null;
  if(shared)return {...shared,reward:shared.reward||{credits:0,uridium:0,xp:0,cores:0},start:Number(shared.start)||Date.now(),end:Number(shared.end)||Date.now()+60000};
  return {...NO_GALAXY_EVENT,start:Date.now(),end:Date.now()+60000};
}
function galaxyEventRecord(ev=currentGalaxyEvent()){normalizeGalaxyEvents();progress.galaxyEvents.records[ev.eventId] ||= {value:0,complete:false,rewarded:false,startedAt:Date.now()};return progress.galaxyEvents.records[ev.eventId];}
function galaxyEventSecondsLeft(ev=currentGalaxyEvent()){return Math.max(0,Math.ceil((ev.end-Date.now())/1000));}
function galaxyEventTimeText(sec){const m=Math.floor(sec/60),s=Math.max(0,sec%60);return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;}
function weekendEventNow(){const serverMs=Number(liveOpsRuntime.state?.server_time);return Number.isFinite(serverMs)&&serverMs>0&&liveOpsRuntime.lastAt?serverMs+Math.max(0,Date.now()-liveOpsRuntime.lastAt):Date.now();}
function formatWeekendCountdown(milliseconds){const total=Math.max(0,Math.ceil(milliseconds/1000));const h=Math.floor(total/3600),m=Math.floor(total%3600/60),s=total%60;return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;}
function weekendEventCalendarHtml(events=liveOpsRuntime.state?.events||[]){
  if(!weekendRotationEnabled(events,liveOpsRuntime.state?.weekend_settings))return '';
  const slots=upcomingWeekendSlots(events,weekendEventNow(),8,liveOpsRuntime.state?.weekend_settings),first=slots[0];
  const formatDay=ms=>new Date(ms).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo',weekday:'short',day:'2-digit',month:'2-digit'}).toUpperCase();
  const formatHour=ms=>new Date(ms).toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit'});
  return `<section class="weekend-event-calendar"><div class="weekend-event-calendar-head"><div><small>GALACTIC WEEKEND EVENTS</small><h3>CALENDÁRIO GALÁCTICO</h3><p>Programação administrável • horário de Brasília</p></div>${first?`<div class="weekend-next"><small>${first.start<=weekendEventNow()?'TERMINA EM':'COMEÇA EM'}</small><b data-weekend-next-countdown data-time="${first.start<=weekendEventNow()?first.end:first.start}">${formatWeekendCountdown((first.start<=weekendEventNow()?first.end:first.start)-weekendEventNow())}</b></div>`:''}</div><div class="weekend-event-schedule">${slots.map(slot=>`<div class="weekend-event-slot ${slot.start<=weekendEventNow()?'playing':''}"><span>${formatDay(slot.start)}</span><b>${formatHour(slot.start)}–${formatHour(slot.end)}</b><strong>${escHtml(slot.icon)} ${escHtml(slot.name)}</strong></div>`).join('')}</div><small class="weekend-event-note">Os eventos ativos avançam em rotação contínua. Consulte o ADM para ajustes de programação.</small></section>`;
}
function refreshWeekendCountdown(){const el=ui.galaxyEventContent?.querySelector('[data-weekend-next-countdown]');if(!el)return;const deadline=Number(el.dataset.time);if(deadline>0)el.textContent=formatWeekendCountdown(deadline-weekendEventNow());}

function isAdminPilot(){const name=String(progress?.profile?.callsign||'').trim().toUpperCase();return name==='FELP22'||!!clanRuntime.state?.is_admin;}
function worldBossOpen(){const wb=worldBossState();return !!wb&&Number(wb.hp)>0;}
function galaxyBattleMapsOpen(){return currentGalaxyEvent().id==='battle'||worldBossOpen()||!!state.currentMap?.battle;}
function galaxyEventEligible(ev=currentGalaxyEvent()){
  if(!progress||state.currentMap?.gate||ev?.informationalOnly)return false;
  const rules=ev?.rules||{};if(rules.battle_only&&!state.currentMap?.battle)return false;
  if(rules.normal_only&&state.currentMap?.battle)return false;
  if(Number(rules.min_tier||0)>Number(state.currentMap?.tier||0))return false;
  const mode=galaxyEventProfile(ev).mode;
  if(mode==='battle_wave')return !!state.currentMap?.battle;
  if(mode==='boss')return !!state.currentMap?.battle||Number(state.currentMap?.tier||1)>=2;
  return !state.currentMap?.battle;
}
function galaxyEventObjectiveText(ev=currentGalaxyEvent(),rec=galaxyEventRecord(ev)){
  if(ev?.informationalOnly){
    const compatible=galaxyEventEligible({...ev,informationalOnly:false});
    return compatible?'SINCRONIZANDO EVENTO NESTE SETOR':'ATIVO EM OUTRO SETOR • '+(ev?.id==='battle'||ev?.rules?.battle_only?'4-1 / 4-2 / 4-3':'MAPAS COMPATÍVEIS');
  }
  if(rec.complete)return 'OBJETIVO CONCLUÍDO • recompensa entregue';
  const profile=galaxyEventProfile(ev),label=profile.progressLabel||'INVASORES',mode=profile.mode;
  if(mode==='convoy')return label+' '+Math.min(100,Math.round(rec.value||0))+'%';
  if(mode==='ore')return fmt(rec.value||0)+' / '+fmt(ev.target)+' '+label;
  if(mode==='battle_wave')return fmt(rec.value||0)+' / '+fmt(ev.target)+' '+label;
  if(mode==='boss')return fmt(rec.value||0)+' / 1 '+label;
  return fmt(rec.value||0)+' / '+fmt(ev.target)+' '+label;
}
function galaxyEventRewardScaled(ev){const mult=1+Math.min(1.5,Math.max(0,(progress?.profile?.level||1)-1)/36);return {credits:Math.round(ev.reward.credits*mult),uridium:Math.round(ev.reward.uridium*mult),xp:Math.round(ev.reward.xp*mult*designerXpMultiplier()*.55),cores:ev.reward.cores||0};}
function triggerCombatFlash(kind='cyan'){
  if(!ui.combatFlash)return;ui.combatFlash.className=`combat-flash flash-${kind}`;void ui.combatFlash.offsetWidth;ui.combatFlash.classList.add('play');setTimeout(()=>ui.combatFlash?.classList.remove('play'),420);
}
