async function sendCloudSaveAttemptV106(){
  // Somente o coordenador V106 invoca esta tentativa; nunca há dois PUTs em paralelo.
  if(offlineFarmWorldLockedV84()||!authenticated||!progress)return 'error';
  cloudBusy=true;setSync('SALVANDO','busy');
  const sentMutation=cloudSaveMutationV105;
  let failed=false;
  try{
    progress.adminResetEpoch=accountResetEpochV478;
    // Salva uma fotografia: recompensas/abates recebidos durante o PUT ficam pendentes.
    const snapshot=structuredClone(progress);
    // V106.2: apenas alteracoes reconhecidas de Hangar podem mudar equipamento.
    // A revisao base e do ultimo estado AUTORITATIVO recebido, nao do localStorage.
    const layoutDiffV1062=equipmentSaveBaselineV109&&equipmentLayoutSignatureV1062(snapshot)!==equipmentLayoutSignatureV1062(equipmentSaveBaselineV109);
    if(layoutDiffV1062&&!equipmentSavePendingV109){
      equipmentRecoveryWarningV109();
      console.error('[hangar-v1062] snapshot de combate tentou remover/equipar sem acao do jogador');
      // Restaurar a CONFIGURACAO validada pelo Supabase; nunca enviar a desmontagem.
      // Protege progressos nao recompensados e escolhas de municao pendentes.
      try{
        const officialGearV1062=await loadCloudSave();
        if(officialGearV1062?.state){
          installEconomyState(officialGearV1062.state,{preservePendingEquipment:false});
          equipmentSaveBaselineV109=structuredClone(officialGearV1062.state);
          showToast('Montagem antiga bloqueada • equipamentos do Supabase restaurados','system');
          return 'retry';
        }
      }catch(recoverErr){console.warn('[hangar-v1062] restauracao segura indisponivel',recoverErr);}
      return 'error';
    }
    const gearIntentV1062=layoutDiffV1062&&equipmentSavePendingV109?
      {intent:'hangar',baseline:equipmentLayoutSignatureV1062(equipmentSaveBaselineV109)}:null;
    const result=await saveCloudSave(snapshot,gearIntentV1062);
    if(result?.statePatch){const patch=result.statePatch;if(Number.isFinite(Number(patch.credits)))progress.profile.credits=Number(patch.credits);if(patch.serverEconomy)progress.serverEconomy={...(progress.serverEconomy||{}),...patch.serverEconomy};localStorage.setItem(saveKey(),JSON.stringify(progress));updateUI();if(patch.serverEconomy?.lastClanCollectionDate)showToast('CLÃ • coleta diária de 10% sincronizada','system');}
    AMMO_SELECTION_V1061.confirm(snapshot);
    cloudDirty=cloudSaveMutationV105!==sentMutation||AMMO_SELECTION_V1061.pending;
    equipmentSaveBaselineV109=structuredClone(snapshot);
    equipmentSavedV109(snapshot);
    if(!cloudDirty)missionSavePendingV105=false;
    if(equipmentSavePendingV109)setSync('HANGAR PENDENTE','busy');
    else if(AMMO_SELECTION_V1061.pending)setSync('MUNICAO PENDENTE','busy');
    else if(!equipmentSaveWarningAtV109)setSync(cloudDirty?'PENDENTE':'ONLINE',cloudDirty?'busy':'ok');
    // Somente o ACK do save com o recibo de conclusão libera a recompensa visível.
    announceCommittedMissionRewardsV108(snapshot.missions);
    // V107: o servidor confirmou o progresso da missão; agora pode receber o prêmio.
    // A conclusão é enviada em outro save. Se este falhar, a missão confirmada
    // continua no servidor e pode ser retomada, sem pagar duas vezes no banco.
    for(const category of confirmedMissionCategoriesV107(snapshot.missions,progress?.missions)){
      const active=progress?.missions?.active?.[category];
      const mission=activeMissionDefinition(category,active);
      if(mission)finishMissionAutomatically(category,mission,active);
    }
    return 'saved';
  }
  catch(e){failed=true;console.warn('cloud save',e);
    if(e?.code==='SAVE_MISSION_STALE'||e?.code==='SAVE_MISSION_UNVERIFIED'||e?.code==='SAVE_EQUIPMENT_INTENT_REQUIRED'||e?.code==='SAVE_EQUIPMENT_STALE'||e?.code==='SAVE_COUPON_STALE'||e?.code==='SAVE_EVENT_STALE'||e?.code==='SAVE_ELITE_STALE'||e?.code==='SAVE_ECONOMY_STALE'||e?.code==='SAVE_NPC_STALE'||e?.code==='SAVE_ORE_STALE'){
      try{
        // Não ressuscita missões concluídas: só recupera aceites e progresso ainda não recompensados.
        const localMissions=structuredClone(progress?.missions||{});
        const remote=await loadCloudSave();
        // Captura DEPOIS do await: o piloto pode ter equipado outro item durante a leitura.
        const desiredGear=equipmentSavePendingV109?structuredClone(progress):null;
        if(remote?.state){
          const merged=mergeUnsavedMissionProgressV105(remote.state.missions,localMissions,category=>missionPeriodKey(category));
          const gearRecovery=desiredGear?reconcilePendingEquipmentV109(remote.state,desiredGear,equipmentSaveBaselineV109):null;
          if(!desiredGear&&(e?.code==='SAVE_EQUIPMENT_INTENT_REQUIRED'||e?.code==='SAVE_EQUIPMENT_STALE')){
            console.warn('[hangar-v1062] snapshot de combate rejeitado: restabelecendo configuracao salva no servidor');
            equipmentRecoveryWarningV109();
          }
          if(e?.code==='SAVE_ELITE_STALE')installServerStatePreservingPosition(remote.state);
          else installEconomyState(remote.state,{preservePendingEquipment:false,preservePendingMissions:false});
          equipmentSaveBaselineV109=structuredClone(remote.state);
          // Uma resposta perdida pode ter gravado a recompensa; o snapshot
          // oficial basta para confirmar, sem tentar pagá-la outra vez.
          announceCommittedMissionRewardsV108(remote.state.missions);
          if(gearRecovery?.ok){
            if(gearRecovery.alreadySaved){
              equipmentSavePendingV109=false;equipmentSaveDesiredV109=null;equipmentSaveWarningAtV109=0;clearEquipmentIntentV1062();saveIntegrityBlockedV106=false;
              setSync('HANGAR SALVO','ok');showToast('Hangar confirmado no Supabase ✓','system');
            }else{
              // O estado de moedas/revisoes veio do SQL, e somente a redistribuicao
              // comprovadamente conservativa dos equipamentos vem do cliente.
              const replacement=gearRecovery.state;
              progress.activeShipId=replacement.activeShipId;
              progress.inventory=replacement.inventory;
              progress.shipLoadout=replacement.shipLoadout;
              progress.drones=replacement.drones;
              if(progress.pet&&replacement.pet){progress.pet.lasers=replacement.pet.lasers;progress.pet.shields=replacement.pet.shields;progress.pet.activeGear=replacement.pet.activeGear;}
              progress.combatConfigsV2013=replacement.combatConfigsV2013;
              computeStats(false);
              saveGame();
              equipmentSaveDesiredV109=structuredClone(progress);
              persistEquipmentIntentV1062();
              scheduleEquipmentSaveV109(180);
            }
          }else if(gearRecovery){
            equipmentSavePendingV109=false;equipmentSaveDesiredV109=null;
            clearEquipmentIntentV1062();equipmentRecoveryWarningV109();
            console.warn('[hangar-v109] conflito sem merge seguro',gearRecovery.reason);
          }
          if(merged.changed){
            progress.missions=merged.missions;
            normalizeMissionState();
            saveGame();
            updateMissionButton();state.missionHudSignature='';renderActiveMissionHud(true);
            if(ui.missionModal&&!ui.missionModal.classList.contains('hidden'))renderMissions();
            // O próximo PUT só transporta a missão preservada com a revisão econômica correta.
            missionSavePendingV105=true;
          }
          // Uma missão 100% concluída e AINDA SEM prêmio precisa ser reenviada.
          // Isso inclui o caso de save antigo rejeitado quando faltava apenas 1 NPC.
          if(pendingMissionCategoriesV107(progress?.missions).length){
            saveGame();missionSavePendingV105=true;
          }
          cloudDirty=merged.changed||cloudDirty||AMMO_SELECTION_V1061.pending||cloudSaveMutationV105!==sentMutation;
          if(equipmentSavePendingV109)setSync('HANGAR PENDENTE','busy');
          else if(!equipmentSaveWarningAtV109)setSync(cloudDirty?'PENDENTE':'ONLINE',cloudDirty?'busy':'ok');
          console.info('[save-reconcile] Economia remota sincronizada; missão ativa preservada quando seguro');
          failed=false;
          return 'retry';
        }
      }catch(syncErr){console.warn('[save-reconcile] Falha ao recuperar sessão',syncErr);}
    }
    if(e?.code==='SAVE_RESET_STALE'){try{localStorage.removeItem(saveKey());}catch{}forceLogoutBecauseSessionMoved('Conta zerada pelo ADM. Faça login novamente para criar seu piloto.');return 'error';}
    if(e?.code==='SAVE_OWNER_MISMATCH'){setSync('BLOQUEADO','err');forceLogoutBecauseSessionMoved('Proteção de conta: um save de outro usuário foi bloqueado.',getUser()?.id||null);return 'error';}
    cloudDirty=true;
    if(equipmentSavePendingV109)equipmentRecoveryWarningV109();
    else setSync('OFFLINE','err');
    return 'error';
  }
  finally{
    cloudBusy=false;
    // Um click em ACEITAR no meio de outro save deve ser confirmado sem depender
    // do usuário repetir o click. Em erro real de rede, evita loop de requisições.
    // O coordenador V106 consolida qualquer alteracao nova na proxima gravacao.
    // Nao agendar um segundo PUT concorrente aqui.
  }
}


// V106 — Single-flight save. Alteracoes surgidas durante um PUT continuam pendentes;
// o proximo PUT recebe o estado atual, nunca o snapshot antigo da fila.
const SAVE_COORDINATOR_V106=createLatestSaveCoordinatorV106({
  hasPending:()=>Boolean(cloudDirty||missionSavePendingV105||equipmentSavePendingV109||AMMO_SELECTION_V1061.pending),
  blocked:()=>!authenticated||!progress||offlineFarmWorldLockedV84(),
  send:()=>sendCloudSaveAttemptV106(),
  onRetry:attempt=>console.info('[save-v106] revisao economica concorrente; reconciliando',attempt),
  maxAttempts:6
});
async function flushCloudSave(force=false){
  return SAVE_COORDINATOR_V106.flush(force);
}

function extraSlotBonusFromLoadout(loadout=progress?.shipLoadout){
  const extras=loadout?.extras||[];
  let bonus=0;
  for(const id of extras)bonus=Math.max(bonus,Number(ITEMS[id]?.slotBonus)||0);
  return bonus;
}
function shipExtraCapacity(shipId=progress?.activeShipId,loadout=progress?.shipLoadout){
  const ship=SHIPS[shipId];if(!ship)return 0;
  return ship.extras+extraSlotBonusFromLoadout(loadout);
}
function activeRepairBot(){
  const extras=progress?.shipLoadout?.extras||[];
  let best=null;
  for(const id of extras){
    const item=ITEMS[id];
    if(!item?.repairRate)continue;
    if(!best||item.repairRate>best.repairRate)best=item;
  }
  return best;
}
function compactEquipmentSlots(list){
  const arr=Array.isArray(list)?list:[];
  const filled=arr.filter(Boolean);
  while(filled.length<arr.length)filled.push(null);
  return filled;
}
function compactEquipmentSlotsInPlace(list){
  if(!Array.isArray(list))return list;
  const compact=compactEquipmentSlots(list);
  list.splice(0,list.length,...compact);
  return list;
}
function compactAllEquipmentSlots(){
  if(!progress)return;
  if(progress.shipLoadout){
    for(const key of ['lasers','generators','extras'])if(Array.isArray(progress.shipLoadout[key]))compactEquipmentSlotsInPlace(progress.shipLoadout[key]);
  }
  for(const d of progress.drones||[])if(Array.isArray(d.slots))compactEquipmentSlotsInPlace(d.slots);
  if(progress.pet){
    if(Array.isArray(progress.pet.lasers))compactEquipmentSlotsInPlace(progress.pet.lasers);
    if(Array.isArray(progress.pet.shields))compactEquipmentSlotsInPlace(progress.pet.shields);
  }
}

function normalizeLoadout(){
  if(!progress)return 0;
  const ship=SHIPS[progress.activeShipId];
  let overflowCount=0;
  for(const type of ['lasers','generators']){
    progress.shipLoadout[type] ||= [];
    const cap=type==='lasers'?ship.lasers:ship.generators;
    while(progress.shipLoadout[type].length<cap)progress.shipLoadout[type].push(null);
    if(progress.shipLoadout[type].length>cap){
      const overflow=progress.shipLoadout[type].splice(cap);
      overflow.filter(Boolean).forEach(id=>{addInventory(id);overflowCount++;});
    }
  }
  progress.shipLoadout.extras ||= [];
  const extraCap=shipExtraCapacity(progress.activeShipId,progress.shipLoadout);
  while(progress.shipLoadout.extras.length<extraCap)progress.shipLoadout.extras.push(null);
  if(progress.shipLoadout.extras.length>extraCap){
    const overflow=progress.shipLoadout.extras.splice(extraCap);
    overflow.filter(Boolean).forEach(id=>{addInventory(id);overflowCount++;});
  }
  for(const key of ['lasers','generators','extras'])compactEquipmentSlotsInPlace(progress.shipLoadout[key]);
  return overflowCount;
}

function addInventory(itemId,count=1){progress.inventory[itemId]=(progress.inventory[itemId]||0)+count;}
function removeInventory(itemId,count=1){
  if((progress.inventory[itemId]||0)<count)return false;
  progress.inventory[itemId]-=count;
  if(progress.inventory[itemId]<=0)delete progress.inventory[itemId];
  return true;
}
function hasExtra(itemId){return !!progress?.shipLoadout?.extras?.includes(itemId);}
function autoLaserEnabled(){return hasExtra('autoLaserCpu');}
function autoRocketEnabled(){return hasExtra('autoRocketCpu');}
function turboRocketEnabled(){return hasExtra('rocketTurboCpu');}
function autoBuyEnabled(){return hasExtra('ammoAutoBuyCpu');}
function liveCatalogKeyForCombat(def){if(!def?.id)return null;if(LASER_AMMO[def.id])return `ammo:${def.id}`;if(ROCKETS[def.id])return `rocket:${def.id}`;return null;}
function canAutoBuy(def){
  if(!def||def.purchasable===false||def.sourceOnly===true)return false;
  const q=liveQuote(liveCatalogKeyForCombat(def));if(!q)return false;
  return q.currency==='credits'?progress.profile.credits>=q.price:progress.profile.uridium>=q.price;
}
