function onScreenWorld(x,y,margin=180){const cam=state.camera,halfW=W/2+margin,halfH=H/2+margin;return x>=cam.x-halfW&&x<=cam.x+halfW&&y>=cam.y-halfH&&y<=cam.y+halfH;}

