const onlineWorld={players:new Map(),busy:false,lastSyncAt:0,lastPresenceSyncAt:0,lastPresenceReadAt:0,lastPresenceReadMap:null,privateRemoved:false};
function clearOnlinePlayers(){if(state.target?.isPlayer){state.target=null;player.laserFiring=false;}onlineWorld.players.clear();}
function shortestAngleDelta(a,b){return Math.atan2(Math.sin(b-a),Math.cos(b-a));}
function upsertRealtimePlayer(raw,spawn=false){
  const id=String(raw?.userId||raw?.id||'');if(!id||id===String(getUser()?.id||''))return null;
  // Patches WebSocket V104 podem conter apenas HP, posicao ou combate.
  // Reconstruir o frame ANTES da interpolacao para nao zerar coordenadas/campos ausentes.
  const previous=onlineWorld.players.get(id)?._worldWireState;raw=spawn||!previous?{...raw}:{...previous,...raw};
  const now=Date.now(),nx=Number(raw.x)||0,ny=Number(raw.y)||0;
  let rp=onlineWorld.players.get(id);if(!rp){rp={id,isPlayer:true,x:nx,y:ny,tx:nx,ty:ny,netX:nx,netY:ny,angle:Number(raw.angle)||0,targetAngle:Number(raw.angle)||0,vx:0,vy:0};onlineWorld.players.set(id,rp);}
  if(!recordRemotePilotPosition(rp,{x:nx,y:ny,angle:raw.angle,receivedAt:now,serverAt:raw.updatedAt,spawn:spawn&&!rp.realtimeUpdatedAt}))return rp;
  rp._worldWireState=raw;
  rp.realtime=true;rp.realtimeUpdatedAt=now;rp.callsign=raw.callsign||rp.callsign||'Pilot';rp.name=rp.callsign;rp.pilotTitle=raw.pilotTitle||rp.pilotTitle||'Piloto Estelar';rp.shipId=raw.shipId||rp.shipId||'phoenix';rp.shipDesignId=raw.shipDesignId||null;rp.faction=raw.faction||rp.faction||null;rp.level=Number(raw.level)||rp.level||1;rp.hp=Number(raw.hp??rp.hp)||0;rp.maxHp=Math.max(1,Number(raw.maxHp??rp.maxHp)||1);rp.shield=Math.max(0,Number(raw.shield??rp.shield)||0);rp.maxShield=Math.max(0,Number(raw.maxShield??rp.maxShield)||0);rp.size=onlineShipSize(rp.shipId)*.48;
  rp.laserFiring=!!raw.laserFiring;rp.laserColor=raw.laserColor||rp.laserColor||'#76d9ff';rp.laserAmmoId=raw.laserAmmoId||rp.laserAmmoId||'lcb10';rp.laserAmmoName=raw.laserAmmoName||rp.laserAmmoName||'PLS-1';rp.targetId=raw.targetId||null;rp.targetIsPlayer=!!raw.targetIsPlayer;
  if(raw.pet?.owned){const q=raw.pet,old=rp.pet||{},qx=Number(q.x)||nx,qy=Number(q.y)||ny,pdt=Math.max(.001,Math.min(1,(now-(old.netAt||now))/1000));rp.pet={...old,owned:true,level:Number(q.level)||1,tx:qx,ty:qy,targetAngle:Number(q.angle)||0,activeGear:q.activeGear||'off',laserTargetId:q.laserTargetId||null,laserActive:!!q.laserActive,laserColor:q.laserColor||rp.laserColor,designId:q.designId||null,netAt:now};if(!old.owned||spawn){rp.pet.x=qx;rp.pet.y=qy;rp.pet.angle=Number(q.angle)||0;rp.pet.vx=0;rp.pet.vy=0;}else{rp.pet.vx=Math.max(-1400,Math.min(1400,(qx-(old.netX??old.tx??qx))/pdt));rp.pet.vy=Math.max(-1400,Math.min(1400,(qy-(old.netY??old.ty??qy))/pdt));}rp.pet.netX=qx;rp.pet.netY=qy;}else rp.pet={owned:false};
  return rp;
}
function remoteTargetEntity(id,isPlayer){if(!id)return null;if(isPlayer){if(String(id)===String(getUser()?.id||''))return {id,isPlayer:true,x:player.x,y:player.y,hp:player.hp};return onlineWorld.players.get(String(id))||null;}return state.enemies.find(e=>e.id===id&&e.hp>0)||null;}
function onlineTerritoryKey(){
  return /^x[1-8]$/.test(progress?.mapId||'')?(currentTerritoryFaction()||progress.profile.faction):'battle';
}
function isPublicPvpSector(mapId=progress?.mapId){return ['b41','b42','b43'].includes(String(mapId||''));}
// Em 4-1, 4-2 e 4-3 todo piloto fora do seu grupo pode ser combatido,
// inclusive da mesma faccao. Fora desses setores, nenhum piloto e alvo PvP.
function onlinePlayerEnemy(rp){return pvpTargetAllowed(rp);}

async function syncOnlineWorld(){
  if(offlineFarmWorldLockedV84()||!authenticated||!progress||onlineWorld.busy)return;
  onlineWorld.busy=true;
  try{
    if(isGalaxyGateMap()){
      clearOnlinePlayers();
      if(!onlineWorld.privateRemoved){onlineWorld.privateRemoved=true;}
      onlineWorld.lastSyncAt=Date.now();return;
    }
    onlineWorld.privateRemoved=false;
    const territory=onlineTerritoryKey();
    await upsertPlayerPresenceOnline({
      callsign:progress.profile.callsign,mapId:progress.mapId,territoryFaction:territory,
      x:player.x,y:player.y,angle:player.angle||0,shipId:progress.activeShipId,faction:progress.profile.faction,pilotTitle:activePilotTitle().label,
      level:progress.profile.level,hp:player.hp,maxHp:player.maxHp,shield:player.shield,maxShield:player.maxShield
    });
    // WS e autoritativo para movimento. SQL fica como fallback e metadados periodicos.
    // Gravar presenca continua a cada ~4,5s: get_map_presence_v12 expira em 9s.
    const readKey=progress.mapId+':'+territory;
    if(sharedUniverseOnline()&&onlineWorld.lastPresenceReadMap===readKey&&Date.now()-onlineWorld.lastPresenceReadAt<14000){
      onlineWorld.lastSyncAt=Date.now();return;
    }
    const rows=await loadMapPresenceOnline(progress.mapId,territory),me=getUser()?.id,seen=new Set();
    onlineWorld.lastPresenceReadAt=Date.now();onlineWorld.lastPresenceReadMap=readKey;
    for(const row of rows){
      if(!row?.user_id||row.user_id===me)continue;seen.add(row.user_id);
      let rp=onlineWorld.players.get(row.user_id);
      if(!rp){rp={id:row.user_id,isPlayer:true,x:Number(row.x)||0,y:Number(row.y)||0,tx:Number(row.x)||0,ty:Number(row.y)||0,angle:Number(row.angle)||0,targetAngle:Number(row.angle)||0};onlineWorld.players.set(row.user_id,rp);}
      // Presence is a coarse fallback. Do not overwrite a pilot while websocket packets remain fresh.
      rp.isPlayer=true;const live=rp.realtime&&Date.now()-(rp.realtimeUpdatedAt||0)<6500;
      if(!live){
        const seenServerAt=Date.parse(row.updated_at||'');
        // Suppress duplicated/stale database snapshots to avoid time-travel on the radar.
        if(!Number.isFinite(rp.lastPresenceMotionAt)||!Number.isFinite(seenServerAt)||seenServerAt>rp.lastPresenceMotionAt){
          recordRemotePilotPosition(rp,{x:row.x,y:row.y,angle:row.angle,receivedAt:Date.now()});
          if(Number.isFinite(seenServerAt))rp.lastPresenceMotionAt=seenServerAt;
        }
        rp.hp=Number(row.hp)||0;rp.maxHp=Number(row.max_hp)||1;rp.shield=Number(row.shield)||0;rp.maxShield=Number(row.max_shield)||0;
      }
      rp.callsign=row.callsign||rp.callsign||'Pilot';rp.name=rp.callsign;rp.shipId=row.ship_id||rp.shipId||'phoenix';rp.faction=row.faction||rp.faction||null;rp.level=Number(row.level)||rp.level||1;
      rp.rankCode=row.rank_code||'pilot_basic';rp.rankTitle=row.rank_title||'Piloto Básico';rp.pilotTitle=row.pilot_title||rp.pilotTitle||'Piloto Estelar';rp.clanTag=row.clan_tag||'';rp.isAdmin=!!row.is_admin;
      rp.territoryFaction=row.territory_faction||territory;rp.size=onlineShipSize(rp.shipId)*.48;rp.updatedAt=row.updated_at;rp.lastPresenceSeenAt=Date.now();
    }
    for(const id of [...onlineWorld.players.keys()]){
      if(!seen.has(id)){
        const rp=onlineWorld.players.get(id),now=Date.now();
        if(rp?.realtime&&now-(rp.realtimeUpdatedAt||0)<5000)continue;
        // Presenca atrasada por uma consulta nao derruba o lock PvP.
        if(state.target?.isPlayer&&state.target.id===id&&now-(rp?.lastPresenceSeenAt||0)<8000)continue;
        if(state.target?.isPlayer&&state.target.id===id){state.target=null;player.laserFiring=false;}
        onlineWorld.players.delete(id);
      }
    }
    onlineWorld.lastSyncAt=Date.now();
  }catch(e){console.warn('online presence sync',e);}
  finally{onlineWorld.busy=false;}
}
let pvpInboxBusy=false,pvpInboxLastAt=0,pvpInboxWasInSectorV104=false;
let pvpExitDrainPendingV106=false;
async function syncPvpInbox(){
  const inPvpV104=isPublicPvpSector();
  if(pvpInboxWasInSectorV104!==inPvpV104){
    // Preserva uma limpeza da inbox ao SAIR da arena: eventos de dano
    // que ficaram em voo nao reaparecem depois em outro PvP.
    if(pvpInboxWasInSectorV104&&!inPvpV104)pvpExitDrainPendingV106=true;
    if(inPvpV104)pvpExitDrainPendingV106=false;
    // Primeira leitura imediata tanto ao entrar quanto ao sair da arena.
    pvpInboxLastAt=0;
    pvpInboxWasInSectorV104=inPvpV104;
  }
  // Em X-1..X-8 (PvE), nunca fazemos polling permanente de dano PvP.
  // Ao sair do Battle Map consumimos a fila UMA vez sem aplicar dano.
  if(!shouldPollPvpInboxV106({
    inPvp:inPvpV104,drainPending:pvpExitDrainPendingV106,
    now:Date.now(),lastReadAt:pvpInboxLastAt,
    busy:pvpInboxBusy,hasSession:!!(authenticated&&progress),
    privateMap:isGalaxyGateMap()
  }))return;
  const exitDrain=!inPvpV104;
  pvpInboxBusy=true;pvpInboxLastAt=Date.now();
  if(exitDrain)pvpExitDrainPendingV106=false;
  try{
    const events=await consumePvpDamageEventsOnline();
    for(const ev of events){
      // Eventos atrasados nunca causam dano depois de sair de um Battle Map.
      if(!isPublicPvpSector())continue;
      const dmg=Math.max(0,Number(ev.damage)||0);
      if(ev.shield_drain){
        const drained=Math.min(player.shield,dmg);player.shield=Math.max(0,player.shield-drained);
        state.lastPlayerDamageAt=nowSec();
        spawnParticle(player.x,player.y-34,`SAB -${fmt(drained)} ESC`,'#79f1ff');
        spawnImpactFx(player.x,player.y,'#79f1ff',38,'shield');
      }else{
        takePlayerDamage(dmg,{forcePvP:true});
        spawnParticle(player.x,player.y-35,`${ev.attacker_callsign||'PILOTO'} -${fmt(dmg)}`,'#ff657d');
      }
    }
    if(events.length){progress.hp=player.hp;progress.shield=player.shield;saveGame();}
  }catch(e){
    if(exitDrain)pvpExitDrainPendingV106=true; // retry unico, backoff 15s se SQL falhar
    console.warn('pvp inbox',e);
  }finally{pvpInboxBusy=false;}
}
function pvpTargetAllowed(target){
  return !!progress && isPublicPvpSector() && !!target?.isPlayer
    && String(target.id||'')!==String(getUser()?.id||'')
    && Number(target.hp)>0 && !isBattleGroupMember(target.id);
}

function pvpLaserBase(ids){
  let dmg=ids.reduce((sum,id)=>sum+(Number(ITEMS[id]?.damage)||0),0);
  const ship=SHIPS[progress.activeShipId],low=['x1','x2','x3','x4'].includes(progress.mapId);
  if(ship?.bonusLowMaps&&low)dmg*=Number(ship.bonusLowMaps.laserMult)||1;
  dmg*=1+pilotLaserPowerBonus();
  dmg*=1+pilotBattleLaserBonus();
  if((Number(state.target?.shield)||0)>0)dmg*=1+pilotShieldPressureBonus();
  return dmg;
}
async function queuePvpShot(target,damage,shieldDrain=false,color='#ff657d'){
  if(!target?.isPlayer||Number(state.pvpShotPending||0)>=3)return null;
  state.pvpShotPending=Number(state.pvpShotPending||0)+1;
  try{
    const row=await queuePvpAttackOnline({
      targetUserId:target.id,damage:Math.max(0,Math.round(damage)),shieldDrain,
      mapId:progress.mapId,territoryFaction:onlineTerritoryKey()
    });
    if(!row?.accepted)throw new Error('Ataque não autorizado.');
    const effective=Math.max(0,Number(row.effective_damage)||0);
    if(shieldDrain&&effective>0){
      const before=player.shield;player.shield=Math.min(player.maxShield,player.shield+effective);
      const restored=Math.max(0,Math.round(player.shield-before));if(restored>0)spawnParticle(player.x,player.y-34,`+${fmt(restored)} ESC`,'#79f1ff');
    }
    if(effective>0){spawnImpactFx(target.x,target.y,shieldDrain?'#79f1ff':color,32,shieldDrain?'shield':'impact');if(target.clanTag&&target.clanTag!==currentClanTag())scoreClanWar(Math.max(1,Math.min(6,Math.floor(effective/50000))),'pvp_damage');}
    return row;
  }catch(e){
    const message=String(e?.message||e).replace(/^.*?:\s*/,''),now=Date.now();
    const limit=/proximo disparo|429|limite de (taxa|requisicoes)|rate.limit/i.test(message);
    const distance=/distante|alcance/i.test(message);
    const permission=/PvP permitido somente|Fogo amigo|mesmo grupo|nivel minimo|sess[aã]o ausente/i.test(message);
    // So interromper em bloqueio real. Erros momentaneos nao cancelam o autoataque.
    if(permission)player.laserFiring=false;
    state.pvpRetryUntil=Math.max(state.pvpRetryUntil||0,now+(limit?160:distance?330:permission?650:900));
    if(!limit && now-(state.pvpErrorLastToastAt||0)>4800){
      state.pvpErrorLastToastAt=now;
      showToast(distance?'Alvo fora do alcance • ataque aguardando aproximacao':permission?message:'PvP sincronizando • laser continua ativo');
    }
    return null;
  }finally{state.pvpShotPending=Math.max(0,Number(state.pvpShotPending||1)-1);}
}
function updateOnlineWorld(dt){
  if(!authenticated||!progress)return;const now=Date.now(),presenceInterval=sharedUniverseOnline()?4500:1200;
  if(now-onlineWorld.lastSyncAt>presenceInterval&&!onlineWorld.busy)syncOnlineWorld();
  // V105.1: somente leitura visual do grupo pode ser mais espaçada com o modal fechado.
  // As verificacoes de membros/recompensas no servidor e as acoes do grupo nao mudam.
  syncPvpInbox();syncClanCreditGrants();
  const groupMenuVisibleV1051=!!(ui.battleGroupModal&&!ui.battleGroupModal.classList.contains('hidden'));
  if(now-battleGroupRuntime.lastAt>(groupMenuVisibleV1051?6000:15000))refreshBattleGroup(false);
  for(const rp of onlineWorld.players.values()){
    // V34.6.3: interpolate buffered remote pilot packets instead of jittery 55ms prediction.
    // Never touch local player position or the server-authoritative combat coordinates.
    if(!advanceRemotePilotVisual(rp,{now,dt})){
      const k=1-Math.exp(-Math.min(.08,Math.max(0,dt))*8);
      rp.x+=((rp.tx??rp.x)-rp.x)*k;rp.y+=((rp.ty??rp.y)-rp.y)*k;
      rp.angle+=shortestAngleDelta(rp.angle,rp.targetAngle||0)*k;
    }
    const q=rp.pet;if(q?.owned){const pk=Math.min(1,dt*14),pgx=(q.tx||q.x||rp.x)+(q.vx||0)*.045,pgy=(q.ty||q.y||rp.y)+(q.vy||0)*.045;q.x+=(pgx-q.x)*pk;q.y+=(pgy-q.y)*pk;q.angle=(q.angle||0)+shortestAngleDelta(q.angle||0,q.targetAngle||0)*Math.min(1,dt*15);}
  }
}
