// V20.2.4: simulação e comandos continuam em cada tick; HUD executa tarefas em ritmos próprios.
const HUD_SCHEDULER=createHudUpdateScheduler();
const HUD_DEFERRED_V72=createDeferredHudScheduler({onError:err=>console.warn('[hud-defer-v72]',err)});
const HUD_BUDGET_V73=createPeriodicHudBudgetV73({intervalMs:1250});
const RENDER_PHASES_V73=createRenderPhaseProfilerV73();
const HUD_CONTENT_CACHE=createHudContentCache();
let periodicHudCall=false;
function updateCriticalHudV2024(){
  if(!progress)return;
  if(ui.coordLabel)HUD_CONTENT_CACHE.text(ui.coordLabel,`${Math.round(player.x)} / ${Math.round(player.y)}`);
  HUD_CONTENT_CACHE.text(ui.hp,fmt(player.hp));
  HUD_CONTENT_CACHE.text(ui.maxHp,fmt(player.maxHp));
  HUD_CONTENT_CACHE.text(ui.shield,fmt(player.shield));
  HUD_CONTENT_CACHE.text(ui.maxShield,fmt(player.maxShield));
  HUD_CONTENT_CACHE.text(ui.speed,fmt(nominalMovementSpeed(player.speed,progress?.mapId,shipAbilitySpeedMultiplier())));
  // V34.6.3: controles de ataque foram removidos da barra de munições.
  // A atualização rápida do HUD deve tolerar sua ausência, como updateUI().
  if(ui.laserToggle)ui.laserToggle.classList.toggle('active',player.laserFiring);
  if(ui.rocketCd)HUD_CONTENT_CACHE.text(ui.rocketCd,rocketReady()?'MÍSSIL PRONTO':`MÍSSIL ${(getRocketCooldown()-(nowSec()-player.lastRocketShot)).toFixed(1)}s`);
  renderBattleConfigHudV2013();
  updateAbilityHud();
  updateBossHud();
  updateTargetLockHud();
  updateCombatStateHud();
}
// V73: atualização periódica DELIMITADA. Evita rodar updateUI() inteiro via callback idle.
