function upgradePilotSkill(id){normalizePilotBio();const skill=PILOT_SKILLS[id],lv=pilotSkillLevel(id);if(!skill||lv>=skill.max)return;const reqInfo=pilotRequirementInfo(skill);if(reqInfo&&!reqInfo.met){showToast(`Requer ${reqInfo.skill.name} nível ${reqInfo.need}/${reqInfo.skill.max}`);return;}if(pilotAvailablePoints()<1){showToast('Você não possui PP disponível');return;}const cost=pilotSkillCreditCost(skill,lv+1);if(progress.profile.credits<cost){showToast(`Faltam ${fmt(cost-progress.profile.credits)} CR`);return;}openSpendConfirm({title:'Evoluir habilidade?',itemName:`${skill.name} • nível ${lv+1}/${skill.max}`,detail:'Confirme para gastar créditos e evoluir esta habilidade da Árvore de Piloto.',value:cost,currency:'credits',confirmLabel:'EVOLUIR HABILIDADE',onConfirm:async()=>{try{const result=await runEconomyAction('pilot_skill_upgrade',{id});computeStats(true);refreshPilotViews();updateUI();showToast(`${skill.name} • nível ${result?.info?.level||lv+1}/${skill.max} • confirmado pelo servidor`);}catch(e){showToast(e.message||'Falha ao gravar pesquisa; nenhum ponto confirmado.');}}});}
function resetPilotTree(){normalizePilotBio();const cost=1000*Math.pow(2,progress.pilotBio.resetCount);if(progress.profile.uridium<cost){showToast(`Reset requer ${fmt(cost)} STL`);return;}if(pilotSpentPoints()<=0){showToast('Nenhum ponto investido para resetar');return;}openSpendConfirm({title:'Resetar Árvore de Piloto?',itemName:`Reset #${progress.pilotBio.resetCount+1}`,detail:'Confirme para gastar Stellarium e resetar todos os pontos investidos.',value:cost,currency:'uridium',confirmLabel:'CONFIRMAR RESET',onConfirm:async()=>{try{await runEconomyAction('pilot_skill_reset',{});computeStats(true);refreshPilotViews();updateUI();showToast('Árvore de Piloto reconfigurada • servidor confirmado');}catch(e){showToast(e.message||'Falha ao reconfigurar; nenhum reset confirmado.');}}});}
