const adminPassEditor={busy:false,snapshot:null,selectedSeasonKey:null};
function adminPassMessage(text,kind='muted'){if(!ui.adminRuntimePassMessage)return;ui.adminRuntimePassMessage.textContent=text||'';ui.adminRuntimePassMessage.className=`admin-runtime-interface-message ${kind}`.trim();}
function adminPassJson(obj){try{return JSON.stringify(obj||{},null,2);}catch{return '{}';}}
function adminPassParseJson(value,label){let parsed;try{parsed=JSON.parse(String(value||'{}'));}catch{throw new Error(`${label}: JSON inválido.`);}if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw new Error(`${label}: use um objeto JSON.`);return parsed;}
function adminPassSelectedSeason(){const seasons=adminPassEditor.snapshot?.seasons||[];const key=adminPassEditor.selectedSeasonKey||adminPassEditor.snapshot?.active_season?.season_key||seasons[0]?.season_key||null;return seasons.find(x=>x.season_key===key)||seasons[0]||null;}
function admPassNewSeasonHtml(){return `<details class="admin-content-creator" id="admNewSeason"><summary>✨ CRIAR TEMPORADA DO PASSE</summary><p class="muted">Nova temporada começa inativa, com tiers criados DESATIVADOS e sem recompensas. Configure e ative quando estiver pronta.</p><div class="admin-shop-fields"><label>ID (ex: 2026-11)<input data-new-season="season_key" maxlength="32"></label><label>NOME<input data-new-season="name" maxlength="80"></label><label>INÍCIO<input data-new-season="starts_at" type="datetime-local"></label><label>FIM<input data-new-season="ends_at" type="datetime-local"></label><label>NÍVEIS DO PASSE<input data-new-season="tier_count" type="number" min="1" max="100" value="30"></label><label>PONTOS POR NÍVEL<input data-new-season="points_per_tier" type="number" min="1" value="500"></label><label>PONTOS DIÁRIOS<input data-new-season="daily_points" type="number" min="1" value="100"></label><label>PREÇO PREMIUM (R$)<input data-new-season="premium_price_brl" type="number" min="0" step=".01" value="19.90"></label></div><label>DESCRIÇÃO<input data-new-season="description" maxlength="240"></label><button class="small-btn gold" type="button" data-new-season-save>CRIAR TEMPORADA</button></details>`;}
async function admSaveNewSeason(){const el=$('#admNewSeason'),f=k=>el?.querySelector(`[data-new-season="${k}"]`)?.value;const d={};for(const k of ['season_key','name','starts_at','ends_at','description'])d[k]=f(k);for(const k of ['tier_count','points_per_tier','daily_points','premium_price_brl'])d[k]=Number(f(k));if(!d.season_key||!d.name||!d.starts_at||!d.ends_at){adminPassMessage('Preencha ID, nome e datas da temporada.','err');return;}if(!await stellarConfirmV4776(`Criar temporada ${d.name} com tiers desativados?`))return;
 try{await adminPassApplyResult(await adminCreatePassSeasonOnline(d),`Temporada ${d.name} criada`);adminPassEditor.selectedSeasonKey=d.season_key;renderAdminPassEditor();showToast('Nova temporada criada!','reward');}catch(e){adminPassMessage(e.message||'Falha ao criar temporada.','err');}}
function renderAdminPassEditor(){
  if(!ui.adminRuntimePassSeason||!ui.adminRuntimePassGrid)return;const season=adminPassSelectedSeason();if(!season){ui.adminRuntimePassSeason.innerHTML=admPassNewSeasonHtml()+'<div class="empty-state">Nenhuma temporada cadastrada. Crie uma acima.</div>';ui.adminRuntimePassGrid.innerHTML='';return;}adminPassEditor.selectedSeasonKey=season.season_key;
  const active=adminPassEditor.snapshot?.active_season?.season_key===season.season_key;
  ui.adminRuntimePassSeason.innerHTML=admPassNewSeasonHtml()+`<label class="admin-pass-switch">ESCOLHER TEMPORADA <select id="admSeasonSelect">${(adminPassEditor.snapshot?.seasons||[]).map(s=>`<option value="${escHtml(s.season_key)}" ${s.season_key===season.season_key?'selected':''}>${escHtml(s.name)} (${escHtml(s.season_key)})</option>`).join('')}</select></label><article class="admin-pass-season-card" data-pass-season="${escHtml(season.season_key)}"><div class="admin-pass-season-head"><div><b>${escHtml(season.name||season.season_key)}</b><small>${escHtml(season.season_key)} • ${active?'ATIVA AGORA':'FORA DA JANELA ATUAL'}</small></div><label class="admin-world-check"><input data-pass-season-field="enabled" type="checkbox" ${season.enabled!==false?'checked':''}> ATIVA</label></div><div class="admin-pass-season-fields"><label>NOME<input data-pass-season-field="name" maxlength="80" value="${escHtml(season.name||'')}"></label><label>INÍCIO<input data-pass-season-field="starts_at" type="datetime-local" value="${escHtml(adminEventDateInput(season.starts_at))}"></label><label>FIM<input data-pass-season-field="ends_at" type="datetime-local" value="${escHtml(adminEventDateInput(season.ends_at))}"></label><label>TIERS<input data-pass-season-field="tier_count" type="number" min="1" max="100" value="${Math.max(1,Number(season.tier_count)||30)}"></label><label>PONTOS / TIER<input data-pass-season-field="points_per_tier" type="number" min="1" max="1000000" value="${Math.max(1,Number(season.points_per_tier)||500)}"></label><label>PONTOS / MISSÃO DIÁRIA<input data-pass-season-field="daily_points" type="number" min="1" max="100000" value="${Math.max(1,Number(season.daily_points)||100)}"></label><label>PREÇO PREMIUM (R$)<input data-pass-season-field="premium_price_brl" type="number" min="0" max="99999" step="0.01" value="${Number(season.premium_price_brl||19.9).toFixed(2)}"></label></div><label class="admin-system-json-label">DESCRIÇÃO<textarea data-pass-season-field="description" maxlength="240">${escHtml(season.description||'')}</textarea></label><button class="small-btn gold" type="button" data-pass-season-save="${escHtml(season.season_key)}">SALVAR TEMPORADA</button></article>`;
  const tierCount=Math.max(1,Number(season.tier_count)||30),stored=new Map([...(adminPassEditor.snapshot?.tiers||[])].filter(x=>String(x.season_key)===String(season.season_key)).map(x=>[Number(x.tier_no),x])),rows=Array.from({length:tierCount},(_,i)=>{const n=i+1;return stored.get(n)||{season_key:season.season_key,tier_no:n,free_reward:fallbackBattlePassRewardDef(n),premium_reward:fallbackPremiumBattlePassRewardDef(n),enabled:true};});
  ui.adminRuntimePassGrid.innerHTML=rows.map(row=>`<article class="admin-pass-tier-card" data-pass-tier="${Number(row.tier_no)}"><div class="admin-pass-tier-head"><b>TIER ${Number(row.tier_no)}</b><label><input data-pass-tier-field="enabled" type="checkbox" ${row.enabled!==false?'checked':''}> ATIVO</label></div><div class="admin-pass-tier-rewards"><label>FREE<textarea data-pass-tier-field="free_reward" spellcheck="false">${escHtml(adminPassJson(row.free_reward))}</textarea></label><label>PREMIUM<textarea data-pass-tier-field="premium_reward" spellcheck="false">${escHtml(adminPassJson(row.premium_reward))}</textarea></label></div><button class="small-btn gold" type="button" data-pass-tier-save="${Number(row.tier_no)}">SALVAR TIER</button></article>`).join('');
}
async function loadAdminPassEditor(force=false){
  if(adminPassEditor.busy)return;adminPassEditor.busy=true;if(ui.adminRuntimePassReload)ui.adminRuntimePassReload.disabled=true;adminPassMessage('Carregando Passe de Temporada...');
  try{const raw=await loadBattlePassRuntimeConfigOnline(!!force);adminPassEditor.snapshot=raw;if(!adminPassEditor.selectedSeasonKey)adminPassEditor.selectedSeasonKey=raw?.active_season?.season_key||raw?.seasons?.[0]?.season_key||null;renderAdminPassEditor();adminPassMessage(`Pass runtime v${Number(raw?.version)||0} • ${raw?.seasons?.length||0} temporada(s) • ${raw?.tiers?.length||0} tiers carregados.`,'ok');}
  catch(e){adminPassMessage(e.message||'Falha ao carregar Passe.','err');}
  finally{adminPassEditor.busy=false;if(ui.adminRuntimePassReload)ui.adminRuntimePassReload.disabled=false;}
}
async function adminPassApplyResult(result,message){const runtime=result?.runtime||await loadBattlePassRuntimeConfigOnline(true);adminPassEditor.snapshot=runtime;normalizePassRuntimeConfig(runtime,'online');savePassRuntimeConfigCache(runtime);renderAdminPassEditor();await Promise.all([loadAdminRuntimeMonitor(false),refreshPremiumState(true).catch(()=>null)]);adminPassMessage(`${message} • Pass v${Number(runtime?.version)||0}.`,'ok');if(ui.passModal&&!ui.passModal.classList.contains('hidden'))renderProgression();return runtime;}
async function saveAdminPassSeason(key,card,button){
  if(adminPassEditor.busy||!key||!card)return;const f=n=>card.querySelector(`[data-pass-season-field="${n}"]`),toIso=v=>{if(!v)return null;const d=new Date(v);return Number.isNaN(d.getTime())?null:d.toISOString();};const starts_at=toIso(f('starts_at')?.value),ends_at=toIso(f('ends_at')?.value);if(!starts_at||!ends_at){adminPassMessage('Informe início e fim válidos.','err');return;}if(new Date(ends_at)<=new Date(starts_at)){adminPassMessage('O fim precisa ser posterior ao início.','err');return;}
  const payload={name:String(f('name')?.value||'').trim(),description:String(f('description')?.value||'').trim(),starts_at,ends_at,tier_count:Math.max(1,Math.min(100,Math.round(Number(f('tier_count')?.value)||30))),points_per_tier:Math.max(1,Math.round(Number(f('points_per_tier')?.value)||500)),daily_points:Math.max(1,Math.round(Number(f('daily_points')?.value)||100)),premium_price_brl:Math.max(0,Number(f('premium_price_brl')?.value)||0),enabled:!!f('enabled')?.checked};if(!payload.name){adminPassMessage('Informe o nome da temporada.','err');return;}adminPassEditor.busy=true;if(button)button.disabled=true;adminPassMessage('Salvando temporada...');try{await adminPassApplyResult(await adminUpdateBattlePassSeasonOnline(key,payload),'Temporada salva');showToast('Passe de Temporada atualizado');}catch(e){adminPassMessage(e.message||'Falha ao salvar temporada.','err');}finally{adminPassEditor.busy=false;if(button)button.disabled=false;}}
async function saveAdminPassTier(tierNo,card,button){
  const season=adminPassSelectedSeason();if(adminPassEditor.busy||!season||!card)return;const f=n=>card.querySelector(`[data-pass-tier-field="${n}"]`);let free_reward,premium_reward;try{free_reward=adminPassParseJson(f('free_reward')?.value,'FREE');premium_reward=adminPassParseJson(f('premium_reward')?.value,'PREMIUM');}catch(e){adminPassMessage(e.message,'err');return;}const payload={free_reward,premium_reward,enabled:!!f('enabled')?.checked};adminPassEditor.busy=true;if(button)button.disabled=true;adminPassMessage(`Salvando Tier ${tierNo}...`);try{await adminPassApplyResult(await adminUpdateBattlePassTierOnline(season.season_key,tierNo,payload),`Tier ${tierNo} salvo`);showToast(`Tier ${tierNo} atualizado`);}catch(e){adminPassMessage(e.message||'Falha ao salvar tier.','err');}finally{adminPassEditor.busy=false;if(button)button.disabled=false;}}

