async function runAdminAction(action,user){if(!user||adminRuntime.busy)return;const name=user.callsign||user.email||'esta conta';let changed=false;try{adminRuntime.busy=true;if(action==='ban'){const minutes=Math.max(0,Number(ui.adminBanDuration?.value)||0),reason=String(ui.adminBanReason?.value||'').trim();if(!await stellarConfirmV4776(`Banir ${name}${minutes?` por ${minutes} minuto(s)`:' permanentemente'}?`))return;await adminBanAccount(user.user_id,{minutes,reason});changed=true;adminSetMessage(`${name} foi banido.`,'ok');}
else if(action==='unban'){if(!await stellarConfirmV4776(`Remover o ban de ${name}?`))return;await adminUnbanAccount(user.user_id);changed=true;adminSetMessage(`Ban removido de ${name}.`,'ok');}
else if(action==='reset'){if(!await stellarConfirmV4776(`ZERAR TODO O PROGRESSO de ${name}?\n\nLogin e callsign serão mantidos. Premium é preservado. O jogador será desconectado.`))return;const resetResult=await adminResetAccount(user.user_id);if(resetResult?.verified!==true||!Number.isSafeInteger(Number(resetResult.reset_epoch)))throw new Error('O banco não confirmou o reset completo.');changed=true;adminSetMessage(`${name} foi zerado e desconectado.`,'ok');}
else if(action==='delete'){const typed=await stellarPromptV4776(`EXCLUSÃO DEFINITIVA.\nDigite exatamente o callsign abaixo para confirmar:\n\n${name}`,'');if(String(typed||'').trim()!==String(name).trim())throw new Error('Exclusão cancelada: callsign não confere.');if(!await stellarConfirmV4776(`ÚLTIMA CONFIRMAÇÃO: deletar ${name}? A pessoa terá que criar uma conta nova.`))return;const deleteResult=await adminDeleteAccount(user.user_id);if(deleteResult?.verified!==true)throw new Error('O banco não confirmou a exclusão definitiva.');changed=true;adminSetMessage(`${name} foi deletado definitivamente.`,'ok');}}catch(err){adminSetMessage(err.message,'err');showToast(err.message);}finally{adminRuntime.busy=false;}if(changed)await refreshAdminPanel();}

function renderAll(){updateBattleGroupBadge();buildAmmoButtons();renderShop();renderHangar();renderCargo();renderMapModal();renderPet();renderMissions();renderGalaxyGate();renderPilotProfile();ensureAuctionState();updatePassBadge();renderGalaxyEvent();updateUI();updateWarfrontBadge();refreshArenaBadge();}

function offlineFarmWorldLockedV84(){return document.body.classList.contains('stellar-offline-active-v485');}
function worldPoint(ev){const r=canvas.getBoundingClientRect(),sx=ev.clientX-r.left,sy=ev.clientY-r.top;return{x:sx-W/2+state.camera.x,y:sy-H/2+state.camera.y};}
function gameplayPointerAllowed(){return !offlineFarmWorldLockedV84()&&authenticated&&progress&&ui.loginModal.classList.contains('hidden')&&ui.shopModal.classList.contains('hidden')&&ui.hangarModal.classList.contains('hidden')&&ui.cargoModal.classList.contains('hidden')&&ui.petModal.classList.contains('hidden')&&ui.missionModal.classList.contains('hidden')&&ui.passModal.classList.contains('hidden')&&ui.gateModal.classList.contains('hidden')&&ui.pilotModal.classList.contains('hidden')&&ui.auctionModal.classList.contains('hidden')&&ui.arenaModal.classList.contains('hidden')&&ui.galaxyEventModal.classList.contains('hidden')&&ui.configModal.classList.contains('hidden')&&ui.mapModal.classList.contains('hidden')&&ui.battleGroupModal.classList.contains('hidden')&&ui.factionModal.classList.contains('hidden');}
function setPointerDestination(ev){const p=worldPoint(ev);player.tx=Math.max(40,Math.min(state.currentMap.world.w-40,p.x));player.ty=Math.max(40,Math.min(state.currentMap.world.h-40,p.y));}
function pointerAction(ev){
  if(!gameplayPointerAllowed()||ev.button!==0)return;
  const p=worldPoint(ev);
  // Prioridade ao sprite do piloto nos Battle Maps; a selecao nao depende da faccao.
  // Testa TODOS os pilotos antes do NPC: isso resolve sobreposicoes na tela e no toque.
  const pilot=[...onlineWorld.players.values()].filter(pvpTargetAllowed)
    .map(rp=>({rp,dist:Math.hypot(rp.x-p.x,rp.y-p.y)}))
    .filter(hit=>hit.dist<=Math.max(50,onlineShipSize(hit.rp.shipId)*.73))
    .sort((a,b)=>a.dist-b.dist)[0]?.rp;
  if(pilot){
    const same=state.target?.id===pilot.id,quick=same&&Date.now()-state.lastTargetTapAt<900;
    if(selectCombatTarget(pilot)){
      state.lastTargetTapId=pilot.id;state.lastTargetTapAt=Date.now();
      setCombatAlert(`PVP 4-X • ${pilot.callsign||'PILOTO'} SELECIONADO`,'combat',1.6);
      if(autoLaserEnabled()||(combatPrefs.tapAttack&&quick))player.laserFiring=true;
      if(quick)showToast(`Ataque iniciado contra ${pilot.callsign||'piloto'}`);
    }
    return;
  }
  // World relay is a native click/touch combat target (not a battle-panel button).
  const clickedRelay=state.currentMap?.battle&&sharedUniverseOnline()?sectorControlState()?.nodes?.filter(n=>n.relayMode&&Math.hypot(n.x-p.x,n.y-p.y)<72).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0]:null;
  if(clickedRelay&&selectRelayWorld(clickedRelay))return;
  const found=state.enemies.find(e=>e.hp>0&&Math.hypot(e.x-p.x,e.y-p.y)<=e.size*1.8+18);
  if(found){const same=state.target?.id===found.id,quick=same&&Date.now()-state.lastTargetTapAt<900;selectCombatTarget(found);state.lastTargetTapId=found.id;state.lastTargetTapAt=Date.now();if(autoLaserEnabled()||(combatPrefs.tapAttack&&quick)){player.laserFiring=true;if(quick)setCombatAlert('LOCK CONFIRMADO • LASER ATIVO','combat',1.2);}return;}
  const clickedPortal=portalAtWorld(p.x,p.y),readyPortal=nearbyPortal();
  if(clickedPortal&&readyPortal&&clickedPortal.to===readyPortal.to&&Math.hypot(clickedPortal.x-readyPortal.x,clickedPortal.y-readyPortal.y)<1){state.pointerNavActive=false;jumpThroughPortal(readyPortal);return;}
  setPointerDestination(ev);state.pointerNavActive=true;state.pointerNavId=ev.pointerId;
  try{canvas.setPointerCapture(ev.pointerId);}catch(_e){}
}
function pointerNavigateMove(ev){if(offlineFarmWorldLockedV84())return;if(!state.pointerNavActive||state.pointerNavId!==ev.pointerId||!gameplayPointerAllowed())return;setPointerDestination(ev);}
function stopPointerNavigation(ev){if(state.pointerNavId!==null&&ev.pointerId!==undefined&&state.pointerNavId!==ev.pointerId)return;state.pointerNavActive=false;state.pointerNavId=null;try{if(ev.pointerId!==undefined)canvas.releasePointerCapture(ev.pointerId);}catch(_e){}}
canvas.addEventListener('pointerdown',e=>{if(AUTOPILOT_V48.active)AUTOPILOT_V48.stop('Controle manual retomado');}, {capture:true});
canvas.addEventListener('pointerdown',pointerAction);
canvas.addEventListener('pointermove',pointerNavigateMove);
canvas.addEventListener('pointerup',stopPointerNavigation);
canvas.addEventListener('pointercancel',stopPointerNavigation);
canvas.addEventListener('lostpointercapture',()=>{state.pointerNavActive=false;state.pointerNavId=null;});
ui.portalPrompt.onclick=()=>{if(offlineFarmWorldLockedV84())return;const portal=nearbyPortal();if(portal)jumpThroughPortal(portal);};
minimap.addEventListener('pointerdown',e=>{if(offlineFarmWorldLockedV84()||!authenticated||!progress)return;e.preventDefault();e.stopPropagation();const r=minimap.getBoundingClientRect();const mx=(e.clientX-r.left)/r.width*minimap.width,my=(e.clientY-r.top)/r.height*minimap.height;player.tx=Math.max(35,Math.min(state.currentMap.world.w-35,mx/minimap.width*state.currentMap.world.w));player.ty=Math.max(35,Math.min(state.currentMap.world.h-35,my/minimap.height*state.currentMap.world.h));showToast(`Rota definida no minimapa`);});
if(ui.laserToggle)ui.laserToggle.onclick=()=>{if(offlineFarmWorldLockedV84())return;if(!state.target||state.target.hp<=0){showToast('Selecione um alvo');return;}player.laserFiring=!player.laserFiring;};if(ui.rocketFire)ui.rocketFire.onclick=()=>{if(!offlineFarmWorldLockedV84())fireRocket(true);};
