function startLoadedGame(){
  if(!telemetryRuntime.sessionOpen)telemetryStartSession();
  state.lastPlayerDamageAt=nowSec();
  normalizeGalaxyGateState();normalizeCombatAbilities();
  if(adminRuntime.status?.is_admin===false&&/^x[1-8]$/.test(progress.mapId)&&progress.territoryFaction&&progress.territoryFaction!==progress.profile.faction){progress.mapId='x1';progress.territoryFaction=progress.profile.faction;}
  const loadedGateKey=gateKeyForMap(progress.mapId);if(loadedGateKey&&!progress.galaxyGate[loadedGateKey]?.run?.active){progress.mapId='x1';progress.territoryFaction=progress.profile.faction;}else if(loadedGateKey)progress.galaxyGate.selected=loadedGateKey;
  const savedLocation=savedLocationForCurrentMap(),savedX=savedLocation?.x??null,savedY=savedLocation?.y??null;
  state.currentMap=MAPS[progress.mapId]||MAPS.x1;state.radarRange=mapRadarRange();
  // Restore the absolute saved vitals. computeStats(true) recalculates based on
  // a stale ratio (from the previous session), which could otherwise refill shield.
  const savedAbsoluteHp=Math.max(0,Number(progress.hp)||0);
  const savedAbsoluteShield=Math.max(0,Number(progress.shield)||0);
  player.hp=savedAbsoluteHp;player.shield=savedAbsoluteShield;
  // Stats are bootstrap-critical. One subsystem must never prevent map/NPC/user initialization.
  try{computeStats(true);}catch(e){
    console.error('[bootstrap] computeStats failed; using safe ship fallback',e);
    const ship=SHIPS[progress.activeShipId]||SHIPS.phoenix;
    player.maxHp=Math.max(1,Number(ship?.hp)||1);player.maxShield=Math.max(0,Number(progress.shield)||0);player.speed=Math.max(1,Number(ship?.speed)||320);
    player.hp=Math.max(1,Math.min(player.maxHp,Number(progress.hp)||player.maxHp));player.shield=Math.max(0,Math.min(player.maxShield,Number(progress.shield)||0));
    progress.hp=player.hp;progress.shield=player.shield;
  }
  player.hp=Math.max(0,Math.min(player.maxHp,savedAbsoluteHp));
  player.shield=clampStoredShieldV2013(savedAbsoluteShield,player.maxShield);
  progress.hp=player.hp;progress.shield=player.shield;
  if(progress.combatConfigsV2013?.profiles?.[progress.combatConfigsV2013.active])progress.combatConfigsV2013.profiles[progress.combatConfigsV2013.active].shield=player.shield;
  positionCheckpointRuntime.lastAt=0;positionCheckpointRuntime.lastX=null;positionCheckpointRuntime.lastY=null;positionCheckpointRuntime.lastKey=null;
  authoritativeLocationRuntime.lastAt=0;authoritativeLocationRuntime.lastX=null;authoritativeLocationRuntime.lastY=null;authoritativeLocationRuntime.lastKey=null;authoritativeLocationRuntime.lastSavedAt=0;authoritativeLocationRuntime.pending=false;
  movementPositionRuntime.wasMoving=false;movementPositionRuntime.lastCommitAt=0;movementPositionRuntime.lastX=null;movementPositionRuntime.lastY=null;movementPositionRuntime.loadedFromCheckpoint=!!savedLocation;movementPositionRuntime.hasMovedSinceLoad=false;movementPositionRuntime.spawnX=savedX;movementPositionRuntime.spawnY=savedY;
  if(isGalaxyGateMap()){
    const gd=galaxyGateDef();player.x=savedX??MAPS[gd.mapId].world.w/2;player.y=savedY??MAPS[gd.mapId].world.h/2;player.tx=player.x;player.ty=player.y;petRuntime.x=player.x+82;petRuntime.y=player.y+64;petRuntime.tx=petRuntime.x;petRuntime.ty=petRuntime.y;petRuntime.roamX=null;petRuntime.roamY=null;petRuntime.nextRoamAt=0;state.camera.x=player.x;state.camera.y=player.y;state.target=null;state.loot=[];state.fx=[];state.rocketFx=[];state.ores=[];state.landmarks=[];state.enemyRespawns=[];state.oreRespawns=[];createBonusBoxes();restoreAlphaGateEnemies();const a=alphaGate(),def=galaxyGateDef().rounds[a.run.round-1],alive=alphaRemainingCount(),now=Date.now();if(a.run.waveIndex<def.waves.length&&!a.run.nextWaveAt){a.run.nextWaveAt=now+GALAXY_ALPHA_WAVE_INTERVAL_MS;}else if(a.run.waveIndex>=def.waves.length&&alive===0&&a.run.round<galaxyGateDef().rounds.length&&!a.run.nextRoundAt){a.run.nextRoundAt=now+GALAXY_ALPHA_ROUND_INTERVAL_MS;}renderAll();preloadActiveGameplayAssets();return;
  }
  const spawnBase=currentBasePoint();player.x=savedX??(['x1','x8'].includes(progress.mapId)?spawnBase.x:400);player.y=savedY??(['x1','x8'].includes(progress.mapId)?spawnBase.y:state.currentMap.world.h/2);player.tx=player.x;player.ty=player.y;petRuntime.x=player.x+82;petRuntime.y=player.y+64;petRuntime.tx=petRuntime.x;petRuntime.ty=petRuntime.y;petRuntime.roamX=null;petRuntime.roamY=null;petRuntime.nextRoamAt=0;state.camera.x=player.x;state.camera.y=player.y;state.target=null;state.loot=[];state.fx=[];state.rocketFx=[];createLandmarks();state.ores=[];state.enemies=[];state.enemyRespawns=[];state.oreRespawns=[];galaxyEventRuntime.mapKey=null;sharedUniverseRuntime.event=null;sharedUniverseRuntime.globalEvent=null;createBonusBoxes();
  try{joinSharedUniverse();}catch(e){console.error('[bootstrap] shared universe join failed',e);}
  try{renderAll();}catch(e){console.error('[bootstrap] initial render failed',e);try{updateUI();}catch{}}
  preloadActiveGameplayAssets();
  if(progress.repairRequired){movePlayerToHomeBase();player.hp=1;player.shield=0;progress.hp=1;progress.shield=0;saveGame();if(premiumActive())resolveDeathRepair({allowAuto:true});else openRepairModal();}
}

async function afterAuth(){
  astralCombatV431.owner=null;astralCombatV431.snapshot=null;++astralCombatV431.request;
  const generation=++gameBootstrapRuntime.generation;
  gameBootstrapRuntime.loading=true;gameBootstrapRuntime.ready=false;gameBootstrapRuntime.lastError=null;
  // V106.8B STARTUP: never block the login panel on secondary farm options or ADM queries.
  // The farm status itself IS critical: use the bounded status-only check, and fail closed.
  authenticated=true;
  adminRuntime.status=null;adminRuntime.enabled=false;
  ui.loginModal.classList.add('hidden');
  setSync('VALIDANDO FARM','busy');
  try { await OFFLINE_FARM_V484.enable(); }
  catch (err) {
    console.error('[bootstrap] farm verification failed closed',err);
    document.body.classList.add('stellar-offline-active-v485');
    setSync('FARM: VERIFICAR','err');
  }
  if(!authenticated||generation!==gameBootstrapRuntime.generation)return;
  void AUTOPILOT_V48.refreshAccess();
  void refreshCommandV22();
  ui.userLabel.textContent=getUser()?.callsign||getUser()?.email?.split('@')[0]||'Pilot';
  loadActivityLog();
  // ADM is secondary. Never hold player loading while a slow admin read runs.
  void refreshAdminStatus(true);
  refreshClanState(true).then(()=>refreshRankings(true)).catch(()=>{});
  setSync(offlineFarmWorldLockedV84()?'FARM: VERIFICAR':'SINCRONIZANDO',offlineFarmWorldLockedV84()?'err':'busy');
  try{
    const accountId=String(getUser()?.id||'');
    if(missionRewardOwnerV108!==accountId){MISSION_REWARD_ACK_V108.reset();missionRewardOwnerV108=accountId;}
    if(ammoSelectionOwnerV1061!==accountId){AMMO_SELECTION_V1061.reset();ammoSelectionOwnerV1061=accountId;}
    let local=readLocalGameState();
    if(local?.accountOwnerId&&String(local.accountOwnerId)!==accountId){
      console.warn('Local save quarantined: owner mismatch');
      try{localStorage.removeItem(saveKey());}catch{}
      local=null;
    }
    const remote=await loadCloudSave();
    saveIntegrityBlockedV106=false;
    equipmentSaveBaselineV109=remote?.state?structuredClone(remote.state):null;
    equipmentSavePendingV109=false;equipmentSaveDesiredV109=null;
    accountResetEpochV478=Math.max(0,Math.trunc(Number(remote?.reset_epoch)||0));
    // Never re-upload an old device save after an ADM reset. A newer local timestamp is irrelevant.
    if(local && Math.max(0,Math.trunc(Number(local.adminResetEpoch)||0))!==accountResetEpochV478){
      try{localStorage.removeItem(saveKey());}catch{}
      local=null;
      console.info('[admin-reset] save local antigo descartado; novo personagem necessário.');
    }
    if(remote?.state?.accountOwnerId&&String(remote.state.accountOwnerId)!==accountId){
      throw Object.assign(new Error('Proteção de conta: o save online está vinculado a outro usuário.'),{code:'SAVE_OWNER_MISMATCH'});
    }
    // Se outra aba resgatou um cupom, nunca preferir o save local antigo mesmo que
    // o timestamp clientSavedAt seja mais recente.
    const authoritativeClaims=remote?.state?.couponClaimsV1821||{};
    const localClaims=local?.couponClaimsV1821||{};
    if(local&&Object.entries(authoritativeClaims).some(([code,at])=>localClaims[code]!==at)){
      console.warn('[coupon] local save sem o prêmio mais recente: usando Supabase');
      local=null;
      try{localStorage.removeItem(saveKey());}catch{}
    }
    const localStamp=Number(local?.clientSavedAt)||0;
    const remoteStamp=Number(remote?.state?.clientSavedAt)||Date.parse(remote?.updated_at||'')||0;
    const localStampSane=localStamp>0&&localStamp<=Date.now()+300000;
    const localGearMismatchV1062=!!(local&&remote?.state&&
      equipmentLayoutSignatureV1062(local)!==equipmentLayoutSignatureV1062(remote.state));
    const gearJournalV1062=readEquipmentIntentV1062();
    const justifiedLocalGearV1062=!!(localGearMismatchV1062&&gearJournalV1062&&
      gearJournalV1062.owner===accountId&&
      gearJournalV1062.baseline===equipmentLayoutSignatureV1062(remote.state)&&
      gearJournalV1062.desired===equipmentLayoutSignatureV1062(local));
    if(localGearMismatchV1062&&!justifiedLocalGearV1062){
      console.warn('[hangar-v1062] descartada montagem local mais nova sem acao explicita; servidor soberano');
      clearEquipmentIntentV1062();
      // Recuperar somente missoes nao recompensadas. Nada de moeda/inventario local.
      const missionRecoveryV1062=mergeUnsavedMissionProgressV105(remote.state.missions,local.missions,category=>missionPeriodKey(category));
      if(missionRecoveryV1062.changed){
        progress=structuredClone(remote.state);progress.missions=missionRecoveryV1062.missions;
        hydrateProgress();saveGame();missionSavePendingV105=true;
        setTimeout(()=>flushCloudSave(true),0);
      }else{progress=structuredClone(remote.state);hydrateProgress();setSync('HANGAR PROTEGIDO','ok');}
    }else if(local&&localStampSane&&localStamp>remoteStamp+250){
      progress=local;hydrateProgress();cloudDirty=true;setSync('LOCAL MAIS NOVO','busy');
      if(remote?.state){
        for(const key of ['selectedLaserAmmo','selectedRocket']){
          if(progress[key]!==remote.state[key]&&AMMO_SELECTION_V1061.accepts(key,progress[key]))AMMO_SELECTION_V1061.mark(key,progress[key]);
        }
      }
      // Um save local de equipamento mais novo continua como pendencia local,
      // nunca como compra confirmada. A reconciliação ocorrerá com a revisão
      // econômica correta no próximo conflito, sem descartar a montagem.
      if(justifiedLocalGearV1062){
        equipmentSavePendingV109=true;
        equipmentSaveDesiredV109=structuredClone(progress);
        persistEquipmentIntentV1062();
        setSync('HANGAR PENDENTE','busy');
      }
      setTimeout(()=>flushCloudSave(true),0);
    }else if(remote.state){
      clearEquipmentIntentV1062();
      progress=remote.state;hydrateProgress();setSync('ONLINE','ok');
    }else if(local){
      progress=local;hydrateProgress();setSync('LOCAL','busy');cloudDirty=true;setTimeout(()=>flushCloudSave(true),0);
    }else{
      progress=null;setSync('ONLINE','ok');
    }
  }catch(err){
    console.warn(err);gameBootstrapRuntime.lastError=err;
    if(err?.code==='SAVE_OWNER_MISMATCH'){authenticated=false;progress=null;signOutLocal();ui.loginModal.classList.remove('hidden');showAuthMode('login');ui.authMessage.textContent=err.message;setSync('BLOQUEADO','err');gameBootstrapRuntime.loading=false;return;}
    loadLocalGame();setSync('OFFLINE','err');
  }
  if(generation!==gameBootstrapRuntime.generation)return;
  if(!progress){gameBootstrapRuntime.loading=false;renderFactionChoice();return;}

  // V18.1.0: aplica cache de configuração imediatamente; atualização online nunca bloqueia o mundo.
  try{loadRuntimeConfigCache();applyRuntimeMenuConfig();}catch(e){console.warn('[runtime-config] cache',e);}
  try{loadNpcRuntimeConfigCache();}catch(e){console.warn('[npc-config] cache',e);}
  try{loadWorldRuntimeConfigCache();}catch(e){console.warn('[world-config] cache',e);}
  try{loadPassRuntimeConfigCache();}catch(e){console.warn('[pass-config] cache',e);}
  try{loadBalanceRuntimeCache();}catch(e){console.warn('[balance-config] cache',e);}

  // 1) Posição local é síncrona e nunca bloqueia o mundo.
  try{restoreLatestRuntimeLocationCheckpoint();}catch(e){console.warn('[bootstrap] local position',e);}

  // 2) Damos uma janela CURTA para o checkpoint dedicado. Nunca mais deixamos RPC externa
  // segurar stats, NPCs, usuários ou o WebSocket indefinidamente.
  let locationPromise=null,locationSettled=false;
  try{
    locationPromise=loadPlayerLocationCheckpointOnline().then(row=>{locationSettled=true;return row;}).catch(e=>{locationSettled=true;console.warn('[bootstrap] server location',e);return null;});
    const first=await Promise.race([locationPromise,bootstrapDelay(650).then(()=>null)]);
    if(first)applyDedicatedCheckpointToProgress(first,{requireNewer:true});
  }catch(e){console.warn('[bootstrap] position race',e);}

  // 3) O MUNDO SOBE AGORA. Premium/LIVE OPS/Designers são secundários e nunca bloqueiam gameplay.
  try{
    startLoadedGame();
    gameBootstrapRuntime.ready=true;
    void refreshAstralCombatV431();
    setSync(offlineFarmWorldLockedV84()?'FARM: MUNDO PAUSADO':'ONLINE',offlineFarmWorldLockedV84()?'busy':'ok');
  }catch(e){
    gameBootstrapRuntime.lastError=e;console.error('[bootstrap] startLoadedGame fatal',e);
    // Última barreira: mantém a nave e tenta o universo mesmo se um render auxiliar falhar.
    try{state.currentMap=MAPS[progress.mapId]||MAPS.x1;const ship=SHIPS[progress.activeShipId]||SHIPS.phoenix;player.maxHp=Math.max(1,Number(ship.hp)||1);player.maxShield=Math.max(0,Number(progress.shield)||0);player.hp=Math.max(1,Math.min(player.maxHp,Number(progress.hp)||player.maxHp));player.shield=Math.max(0,Math.min(player.maxShield,Number(progress.shield)||0));player.x=Number(progress.x)||currentBasePoint().x;player.y=Number(progress.y)||state.currentMap.world.h/2;player.tx=player.x;player.ty=player.y;state.camera.x=player.x;state.camera.y=player.y;joinSharedUniverse();syncOnlineWorld();updateUI();gameBootstrapRuntime.ready=true;}catch(inner){console.error('[bootstrap] emergency fallback failed',inner);}
  }finally{gameBootstrapRuntime.loading=false;}

  renderChatTabs();refreshChatHistory(true);updatePassBadge();refreshBonusRuntime(true).catch(()=>{});syncAuctionBidsOnline();syncOnlineWorld();syncClanCreditGrants(true);refreshClanState(true);refreshWarfrontState(true).catch(()=>{});refreshRuntimeConfig(true).catch(()=>{});refreshNpcRuntimeConfig(true).catch(()=>{});refreshWorldRuntimeConfig(true).catch(()=>{});refreshSystemsRuntimeConfig(true).catch(()=>{});refreshPassRuntimeConfig(true).catch(()=>{});refreshShopsRuntimeConfig(true).catch(()=>{});refreshBalanceRuntime(true).catch(()=>{});

  // Se a posição do servidor chegou depois dos 650ms e o jogador ainda não moveu a nave,
  // ela pode corrigir o ponto inicial sem tocar em economia/inventário.
  if(locationPromise&&!locationSettled){locationPromise.then(row=>{if(row&&generation===gameBootstrapRuntime.generation&&!movementPositionRuntime.hasMovedSinceLoad)reapplyDedicatedCheckpointToLiveWorld(row);}).catch(()=>{});}

  // Serviços não críticos em background. Designers podem alterar stats, então recalculamos ao terminar.
  Promise.allSettled([refreshPremiumState(true),refreshLiveOpsState(true),refreshDesignerState(true)]).then(()=>{
    if(generation!==gameBootstrapRuntime.generation||!authenticated||!progress)return;
    try{computeStats(true);buildAmmoButtons();refreshPetViews();renderShop();updateUI();syncSharedUniversePlayer(true);syncOnlineWorld();}catch(e){console.warn('[bootstrap] background refresh',e);}
  });

  // Watchdogs curtos: se WS/presença ainda não tiverem snapshot, tenta novamente sem bloquear o usuário.
  setTimeout(()=>{if(!offlineFarmWorldLockedV84()&&generation===gameBootstrapRuntime.generation&&authenticated&&progress&&sharedUniverseMap()&&!sharedUniverseRuntime.ready){try{joinSharedUniverse();}catch{}syncOnlineWorld();}},2500);
  setTimeout(()=>{if(!offlineFarmWorldLockedV84()&&generation===gameBootstrapRuntime.generation&&authenticated&&progress&&sharedUniverseMap()&&!sharedUniverseRuntime.ready){try{sharedUniverse.close();joinSharedUniverse();}catch{}syncOnlineWorld();}},6500);
}

async function boot(){
  ui.loginModal.classList.remove('hidden');showAuthMode('login');setSync('LOCAL','');
  try{
    const recovery=await restorePasswordRecoveryFromUrl();
    if(recovery){showAuthMode('recovery');ui.authMessage.textContent='Defina sua nova senha para concluir a recuperação.';return;}
    // Exceção de segurança: após iniciar OAuth nesta aba, o retorno do Google
    // é um login explícito. O backend ainda registra a sessão única do jogo.
    const googleSignIn = await restoreGoogleSignInFromUrl();
    if (googleSignIn) { await afterAuth(); return; }
    // V101: APK opt-in -> sessão criptografada; Web -> somente sessionStorage da aba.
    // A restauração sempre confirma a sessão única com o servidor antes de acessar o save.
    ui.authMessage.textContent='Verificando sessão salva...';
    const restored=await restoreSession();
    if(restored){if(ui.loginPassword)ui.loginPassword.value='';await afterAuth();return;}
    if(ui.loginPassword)ui.loginPassword.value='';
    const restoreError=getSessionRestoreErrorV101();
    if(restoreError?.code==='NETWORK_TIMEOUT'||restoreError?.code==='NETWORK_OFFLINE'){
      ui.authMessage.textContent='Sem conexão para validar a sessão salva. Reconecte para continuar ou entre manualmente.';
      ui.loginRetrySessionBtn?.classList.remove('hidden');
    }else{
      ui.authMessage.textContent=canRememberSessionV101()?'Entre uma vez e marque “Manter conectado” para as próximas aberturas.':'Entre para acessar sua conta. Seu e-mail pode ficar salvo.';
    }
  }catch(err){console.warn('[login] falha na inicialização',err?.code||err?.message);ui.loginModal.classList.remove('hidden');ui.authMessage.textContent='Falha ao preparar o jogo: '+String(err?.message||'Faça login novamente.')+' • O save online não foi alterado.';}
}

