const AUTO_QUALITY_ORDER=['low','medium','high'];
let perfWindowStart=performance.now(),perfFrames=0,perfGoodWindows=0,perfLastChange=0;
function monitorAutoPerformance(t){
  if(qualityMode!=='auto'){perfWindowStart=t;perfFrames=0;perfGoodWindows=0;return;}
  perfFrames++;
  const elapsed=t-perfWindowStart;if(elapsed<5000)return;
  const fps=perfFrames*1000/Math.max(1,elapsed),current=resolvedQualityMode(),idx=AUTO_QUALITY_ORDER.indexOf(current),ceiling=AUTO_QUALITY_ORDER.indexOf(AUTO_QUALITY_CEILING),target=current==='high'?30:current==='medium'?30:45;
  if(t-perfLastChange>9000&&fps<target*.86&&idx>0){perfLastChange=t;perfGoodWindows=0;applyAutoQualityResolution(AUTO_QUALITY_ORDER[idx-1],true);}
  else if(fps>target*.94){perfGoodWindows++;if(perfGoodWindows>=2&&t-perfLastChange>12000&&idx<ceiling){perfLastChange=t;perfGoodWindows=0;applyAutoQualityResolution(AUTO_QUALITY_ORDER[idx+1],true);}}
  else perfGoodWindows=0;
  perfWindowStart=t;perfFrames=0;
}
const FRAME_GATE_V20210=createFrameGate();
let last=performance.now();FRAME_GATE_V20210.reset(last);
// V34.6.3: o próximo quadro é sempre agendado, mesmo se UI/efeitos falharem.
// O erro aparece nos logs e num aviso leve, sem provocar loop infinito de notificações.
const frameRecoveryV3031={errors:0,lastLog:0,lastToast:0};
function loop(t){
  try{
    if(document.visibilityState==='hidden'||offlineFarmWorldLockedV84()){
      // V84: mundo congelado de verdade; menus HTML e operações remotas continuam ativos.
      last=t;FRAME_GATE_V20210.reset(t);PERF_MONITOR.pause();return;
    }
    const allowed=FRAME_GATE_V20210.accept(t,qualityProfile().fps);
    if(PERF_MONITOR.isEnabled())PERF_MONITOR.recordTick(t,allowed);
    if(!allowed)return;
    const frameInterval=t-last;
    // V74: never reset the bitmap AFTER the final draw. Buffer clear at the end
    // of a frame was visible as screen flicker until the next rAF.
    if(pendingCanvasResolutionV74){pendingCanvasResolutionV74=false;resize();}
    const dt=Math.min(Math.max(0,frameInterval/1000),.05);last=t;
    const inSettings=isSettingsOpenV2029();
    const adaptiveFrameStart=DEVICE_CAPS.mobile&&!inSettings?performance.now():0;
    if(PERF_MONITOR.isEnabled()){
      const start=performance.now(),phases={};update(dt,phases);
      const renderStart=performance.now();if(!inSettings)draw();const end=performance.now();
      PERF_MONITOR.record(t,end-start,qualityProfile().fps,{updateMs:renderStart-start,drawMs:end-renderStart,phases,context:inSettings?'settings':'game'});
      const v75status=VISUAL_ISOLATION_V75.frame(t,{visible:true,inSettings,mapId:progress?.mapId||'',quality:resolvedQualityMode(),width:canvas.width,height:canvas.height,intervalMs:frameInterval,workMs:end-start,drawMs:end-renderStart,updateMs:renderStart-start});
      if(v75status==='completed'||v75status==='cancelled'||v75status==='started')syncVisualIsolationV75();
    }else{update(dt);if(!inSettings)draw();}
    // Amostras para ajuste visual não alteram o delta time ou o frame gate.
    if(adaptiveFrameStart&&ADAPTIVE_CANVAS_V70.observe(t,performance.now()-adaptiveFrameStart,frameInterval))pendingCanvasResolutionV74=true;
    monitorAutoPerformance(t);
    if(frameRecoveryV3031.errors)frameRecoveryV3031.errors=0;
  }catch(err){
    last=t;FRAME_GATE_V20210.reset(t);
    frameRecoveryV3031.errors++;
    if(t-frameRecoveryV3031.lastLog>3000){
      frameRecoveryV3031.lastLog=t;
      console.error('[stellar-frame-recovery V34.6.3]',err);
      // Não enviar diagnósticos nem dados do usuário a serviços externos.
    }
    if(t-frameRecoveryV3031.lastToast>15000){
      frameRecoveryV3031.lastToast=t;
      try{showToast('Falha de quadro recuperada; verifique o console se persistir.','system');}catch{}
    }
  }finally{requestAnimationFrame(loop);}
}requestAnimationFrame(loop);
